def _get_analysis_pool(size: int = 5) -> ThreadPoolExecutor:
    global _ANALYSIS_POOL
    with _ANALYSIS_POOL_LOCK:
        if _ANALYSIS_POOL is None:
            # 8GB Android balanced: 5 parallel symbol analyses keep the bar moving
            # without saturating SSL/RAM. Pool is process-wide and reused.
            n = max(2, min(int(size), int(os.environ.get("TITAN_SCAN_WORKERS", "8") or 8)))
            _ANALYSIS_POOL = ThreadPoolExecutor(max_workers=n, thread_name_prefix="titan-an")
        return _ANALYSIS_POOL


