def _query_int(name: str, default: int, lo: int, hi: int) -> int:
    """Parse bounded integer query parameters without turning bad URLs into 500s."""
    try:
        value = int(request.args.get(name, default))
    except (TypeError, ValueError):
        value = int(default)
    return max(int(lo), min(int(value), int(hi)))


def _query_timeframe(name: str = "timeframe", default: str = "1h") -> str:
    value = str(request.args.get(name, default) or default).strip()
    # Binance-supported TITAN analysis frames. Reject arbitrary strings early.
    return value if value in {"15m", "1h", "4h", "1d"} else default

_MAINTENANCE_LOCK = threading.Lock()

def _safe_background_forecast_maintenance():
    if not _MAINTENANCE_LOCK.acquire(blocking=False):
        return
    if not TITAN_V51_AUTHORITATIVE:
        try:
            v32_evaluate_pending()
            v32_register_learning_maintenance()
        except Exception as exc:
            LOGGER.warning("V32 learning maintenance failed: %s", exc)
        try:
            evaluate_pending_forecasts()
        except Exception as exc:
            LOGGER.warning("Background forecast maintenance failed: %s", exc)
        try:
            evaluate_paper_trades()
        except Exception as exc:
            LOGGER.warning("Background paper-trade maintenance failed: %s", exc)
    try:
        autonomous_performance_maintenance(False)
    except Exception as exc:
        LOGGER.debug("Autonomous performance maintenance failed: %s", exc)
    finally:
        _MAINTENANCE_LOCK.release()

# --- V53.1 UI: signal ordering + neon tiers for dashboard cards -------------
def _titan_ui_family(item: Any) -> str:
    try:
        dec = str((item.get("stance_family") or item.get("decision_tag") or "WAIT")).upper()
    except Exception:
        return "WAIT"
    return dec if dec in ("LONG", "SHORT") else "WAIT"


def titan_sort_signals(rows: Any, limit: Optional[int] = None, only_active: bool = False) -> list:
    """Dashboard display order: LONG (strongest first) -> SHORT (strongest first) -> WAIT.

    Strength is directional: LONG uses score, SHORT uses 100-score (lower score = stronger
    bearish edge), WAIT uses the raw score. Ties are broken by signal quality, success
    probability and opportunity score. Also tags neon tiers (elite / good) per side and
    TF direction dots (up / down). Display only — analysis values are never modified.
    """
    fam_order = {"LONG": 0, "SHORT": 1, "WAIT": 2}
    items = []
    for raw in rows or []:
        if not isinstance(raw, dict):
            continue
        x = dict(raw)
        fam = _titan_ui_family(x)
        sc = safe_float(x.get("score"), 50.0)
        strength = sc if fam == "LONG" else (100.0 - sc) if fam == "SHORT" else sc
        x["ui_family"] = fam
        x["ui_strength"] = round(float(clamp(strength, 0.0, 100.0)), 1)
        tfs = x.get("tfs") if isinstance(x.get("tfs"), dict) else {}
        dirs = {}
        for tf in ("15m", "1h", "4h", "1d"):
            v = safe_float(tfs.get(tf, x.get("tfs" + tf, sc)), sc)
            dirs[tf] = "up" if v >= 50.0 else "down"
        x["ui_tfdir"] = dirs
        items.append(x)
    if only_active:
        items = [x for x in items if x["ui_family"] != "WAIT"]
    items.sort(key=lambda x: (
        fam_order.get(x["ui_family"], 2),
        -x["ui_strength"],
        -safe_float(x.get("signal_quality"), 0.0),
        -safe_float(x.get("success_probability"), 0.0),
        -safe_float(x.get("opportunity_score"), 0.0),
    ))
    counts = {"LONG": 0, "SHORT": 0, "WAIT": 0}
    for x in items:
        counts[x["ui_family"]] += 1
    rank = {"LONG": 0, "SHORT": 0, "WAIT": 0}
    for x in items:
        fam = x["ui_family"]
        r = rank[fam]
        x["ui_rank"] = r + 1
        x["ui_group_start"] = (r == 0)
        x["ui_group_count"] = counts[fam]
        grade = str(x.get("grade") or "")
        glow = ""
        if fam != "WAIT":
            if (r < 2 and x["ui_strength"] >= 60) or grade == "A+" or x["ui_strength"] >= 78:
                glow = "glowElite"
            elif r < 5 or grade == "A" or x["ui_strength"] >= 64:
                glow = "glowGood"
        x["ui_glow"] = glow
        rank[fam] = r + 1
    if limit:
        items = items[: int(limit)]
    return items


try:
    app.jinja_env.globals["titan_sort_signals"] = titan_sort_signals
except Exception:
    _swallow()


def _index_base():
    # Fast-but-complete bootstrap: if a usable snapshot exists, render it immediately.
    # On a cold start, wait for the market engine ONCE so the user receives the full coin
    # dashboard exactly like the original build. The engine itself is parallelized and
    # Gemini is non-blocking, making the cold start substantially faster without a blank UI.
    try:
        t0 = time.perf_counter()
        market_data, gemini_summary, macro = _fast_market_snapshot()
        with CACHE_LOCK:
            cache_age = time.time() - float(CACHE.get("timestamp") or 0) if CACHE.get("timestamp") else 1e9
        # Never block the first paint on a full multi-coin analyze when any snapshot exists.
        # Cold start without disk cache: kick background refresh and render lightweight empty shell.
        if not market_data:
            # Never block the HTTP request on a full multi-coin scan (Android/mobile).
            # Show emergency live prices immediately, then refresh analysis in background.
            try:
                emergency = _emergency_live_cards()
                if emergency:
                    market_data = emergency
                    with CACHE_LOCK:
                        if not CACHE.get("data"):
                            CACHE["data"] = emergency
                            CACHE["timestamp"] = time.time()
            except Exception as _em_exc:
                LOGGER.warning("index emergency cards: %s", _em_exc)
            _background_market_refresh(True)
        elif cache_age >= MARKET_CACHE_TTL:
            _background_market_refresh(False)
        if RENDER_PERF_LOG:
            LOGGER.info("index snapshot ready in %.0fms coins=%s age=%.1fs",
                        (time.perf_counter() - t0) * 1000, len(market_data or []), cache_age if market_data else -1)
    except Exception as exc:
        LOGGER.exception("Index market bootstrap error: %s", exc)
        market_data, gemini_summary, macro = _fast_market_snapshot()
        if not market_data:
            _background_market_refresh(False)
    # Historical evaluation is maintenance work; never hold up dashboard rendering.
    threading.Thread(target=lambda: _safe_background_forecast_maintenance(), name="titan-forecast-maint", daemon=True).start()
    return _v59_page_response()



