@app.get("/api/performance-learning")
def api_performance_learning():
    try:
        symbol=request.args.get("symbol","").strip() or None
        v32_evaluate_pending()
        matrix=v32_performance_matrix(symbol)
        learning=v32_learning_profile(_normalize_symbol(symbol)) if symbol else None
        with DB_LOCK, db_conn() as con:
            total=con.execute("SELECT COUNT(*) FROM v32_forecast_audit").fetchone()[0]
            pending=con.execute("SELECT COUNT(*) FROM v32_forecast_audit WHERE outcome='PENDING'").fetchone()[0]
            wins=con.execute("SELECT COUNT(*) FROM v32_forecast_audit WHERE outcome='WIN'").fetchone()[0]
            losses=con.execute("SELECT COUNT(*) FROM v32_forecast_audit WHERE outcome='LOSS'").fetchone()[0]
            wait_ok=con.execute("SELECT COUNT(*) FROM v32_forecast_audit WHERE outcome='WAIT_CORRECT'").fetchone()[0]
            wait_missed=con.execute("SELECT COUNT(*) FROM v32_forecast_audit WHERE outcome='WAIT_MISSED'").fetchone()[0]
        dec=wins+losses
        # Keep technical backtest snapshots separate from the live forecast audit:
        # these snapshots are not realized live trades and must never inflate live WR.
        snapshot_where = "WHERE oos_status='ok'"
        snapshot_args = []
        if symbol:
            snapshot_where += " AND symbol=?"
            snapshot_args.append(_normalize_symbol(symbol))
        with DB_LOCK, db_conn() as con:
            snapshot_rows = con.execute(
                f"""SELECT timeframe, COUNT(*) AS snapshots,
                           COUNT(DISTINCT symbol) AS symbols,
                           ROUND(AVG(trades), 2) AS avg_trades,
                           ROUND(AVG(win_rate), 2) AS avg_win_rate,
                           ROUND(AVG(expectancy), 4) AS avg_expectancy,
                           ROUND(AVG(profit_factor), 4) AS avg_profit_factor,
                           ROUND(AVG(max_drawdown), 4) AS avg_max_drawdown,
                           MAX(created_at) AS latest_at
                    FROM performance_snapshots {snapshot_where}
                    GROUP BY timeframe ORDER BY timeframe""",
                snapshot_args,
            ).fetchall()
            snapshot_total = con.execute(
                f"SELECT COUNT(*) FROM performance_snapshots {snapshot_where}", snapshot_args
            ).fetchone()[0]
        backtest_proxy = {
            "source": "performance_snapshots",
            "scope": "technical_proxy_backtest_not_live_trades",
            "snapshot_count": int(snapshot_total or 0),
            "by_timeframe": [dict(r) for r in snapshot_rows],
            "semantics": "averages of stored snapshots; not pooled trade-level statistics",
        }
        return jsonify({"ok":True,"version":V32_VERSION,"timeframe_policy":V59_TF_POLICY,"matrix":matrix,"learning":learning,
                        "summary":{"total":total,"pending":pending,"wins":wins,"losses":losses,
                                   "directional_win_rate":round(wins/dec*100,1) if dec else None,
                                   "wait_correct":wait_ok,"wait_missed":wait_missed},
                        "backtest_proxy":backtest_proxy})
    except Exception as exc:
        LOGGER.exception("V32 performance endpoint failed")
        return jsonify({"ok":False,"error":str(exc)}),500

