def _central_load_weights() -> None:
    global _CENTRAL_WEIGHTS
    try:
        with DB_LOCK, db_conn() as con:
            rows = con.execute(
                "SELECT component,samples,wins,losses,reward_sum,penalty_sum,weight FROM central_component_stats"
            ).fetchall()
        weights = dict(_CENTRAL_WEIGHTS_DEFAULT)
        for row in rows:
            name, samples, wins, losses, reward, penalty, w = row
            # Ignore components from retired decision generations.  Otherwise an
            # old DB can silently resurrect removed/circular voters.
            if name not in _CENTRAL_WEIGHTS_DEFAULT:
                continue
            n = int(samples or 0)
            if n >= 12:
                wr = (wins or 0) / max(1, (wins or 0) + (losses or 0))
                reliability = clamp(0.55 + (wr - 0.5) * 1.4, 0.35, 1.55)
                # mild reward/penalty tilt
                tilt = 1.0 + 0.04 * safe_float(reward, 0) - 0.05 * safe_float(penalty, 0)
                w = clamp(safe_float(_CENTRAL_WEIGHTS_DEFAULT.get(name), 1.0) * reliability * tilt, 0.25, 2.4)
            else:
                w = safe_float(_CENTRAL_WEIGHTS_DEFAULT.get(name), 1.0)
            weights[name] = float(w)
        with _CENTRAL_WEIGHT_LOCK:
            _CENTRAL_WEIGHTS = weights
    except Exception as exc:
        LOGGER.debug("central weight load: %s", exc)


_central_init_schema()
_edge_lab_init_schema()
_central_load_weights()


def _central_votes(item: dict[str, Any]) -> dict[str, dict[str, Any]]:
    votes: dict[str, dict[str, Any]] = {}
    tf = item.get("tf_scores") or item.get("tfs") or {}
    s15 = safe_float(tf.get("15m"), 50.0)
    s1h = safe_float(tf.get("1h"), 50.0)
    s4h = safe_float(tf.get("4h"), 50.0)
    s1d = safe_float(tf.get("1d"), 50.0)
    htf = 0.55 * s4h + 0.45 * s1d
    mtf = s1h
    ltf = s15

    def _from_score(sc: float) -> tuple[float, float, str]:
        lean = clamp((sc - 50.0) / 50.0, -1.0, 1.0)
        conf = clamp(abs(sc - 50.0) / 50.0, 0.0, 1.0)
        side = "LONG" if lean > 0.08 else "SHORT" if lean < -0.08 else "WAIT"
        return lean, conf, side

    for key, sc, label in (
        ("htf_trend", htf, "روند کلان 4h/1d"),
        ("mtf_setup", mtf, "ستاپ 1h"),
        ("ltf_trigger", ltf, "تریگر 15m"),
    ):
        lean, conf, side = _from_score(sc)
        votes[key] = {"lean": lean, "confidence": conf, "side": side, "raw": sc, "label": label}

    score = safe_float(item.get("score"), 50.0)
    lean, conf, side = _from_score(score)
    votes["momentum"] = {"lean": lean, "confidence": conf, "side": side, "raw": score, "label": "مومنتوم هسته"}

    structure = item.get("structure") or {}
    sb = str(structure.get("bias") or item.get("structure_bias") or item.get("bias") or "")
    if sb in {"صعودی", "LONG"}:
        lean, conf = 0.55, 0.55
    elif sb in {"نزولی", "SHORT"}:
        lean, conf = -0.55, 0.55
    else:
        lean, conf = 0.0, 0.2
    votes["structure"] = {
        "lean": lean, "confidence": conf,
        "side": "LONG" if lean > 0 else "SHORT" if lean < 0 else "WAIT",
        "raw": sb or "خنثی", "label": "ساختار قیمت",
    }

    taker_buy = safe_float(item.get("taker_buy_pct"), 50.0)
    if taker_buy == 50 and isinstance(item.get("buy_sell"), dict):
        taker_buy = safe_float((item.get("buy_sell") or {}).get("buy_pct"), 50.0)
    vol_lean = clamp((taker_buy - 50.0) / 35.0, -1.0, 1.0)
    votes["volume_flow"] = {
        "lean": vol_lean,
        "confidence": clamp(abs(taker_buy - 50.0) / 35.0, 0.0, 1.0),
        "side": "LONG" if vol_lean > 0.12 else "SHORT" if vol_lean < -0.12 else "WAIT",
        "raw": taker_buy, "label": "جریان حجم",
    }

    deriv = item.get("derivatives") if isinstance(item.get("derivatives"), dict) else {}
    funding = safe_float(item.get("funding_value"), safe_float(deriv.get("funding_value"), 0.0))
    oi_delta = safe_float(item.get("oi_delta"), safe_float(deriv.get("oi_delta"), 0.0))
    fund_lean = clamp(-funding * 8.0, -1.0, 1.0)
    oi_lean = clamp(oi_delta / 8.0, -1.0, 1.0)
    d_lean = clamp(0.6 * fund_lean + 0.4 * oi_lean, -1.0, 1.0)
    votes["derivatives"] = {
        "lean": d_lean, "confidence": clamp(abs(d_lean), 0.0, 1.0),
        "side": "LONG" if d_lean > 0.12 else "SHORT" if d_lean < -0.12 else "WAIT",
        "raw": {"funding": funding, "oi_delta": oi_delta}, "label": "مشتقات",
    }

    patterns = item.get("patterns") or item.get("pattern_pack") or {}
    pbias = safe_float(patterns.get("score_bias") if isinstance(patterns, dict) else 0.0, safe_float(item.get("pattern_bias"), 0.0))
    p_lean = clamp(pbias / 4.0, -1.0, 1.0)
    votes["pattern"] = {
        "lean": p_lean, "confidence": clamp(abs(p_lean), 0.0, 1.0),
        "side": "LONG" if p_lean > 0.15 else "SHORT" if p_lean < -0.15 else "WAIT",
        "raw": pbias, "label": "الگوی نموداری",
    }

    fc = item.get("candle_forecast") or item.get("forecast") or {}
    fc_bias = str(fc.get("overall_bias") or "")
    if fc_bias == "صعودی":
        f_lean, f_conf = 0.45, 0.4
    elif fc_bias == "نزولی":
        f_lean, f_conf = -0.45, 0.4
    else:
        f_lean, f_conf = 0.0, 0.15
    path_strength = safe_float(fc.get("path_strength"), 0.0) / 40.0
    f_conf = clamp(f_conf + path_strength * 0.3, 0.0, 1.0)
    votes["forecast_path"] = {
        "lean": f_lean, "confidence": f_conf,
        "side": "LONG" if f_lean > 0 else "SHORT" if f_lean < 0 else "WAIT",
        "raw": fc_bias or "خنثی", "label": "مسیر پیش‌بینی",
    }

    # Do NOT vote the previous canonical decision back into the new canonical
    # decision.  It is derived from many of the same inputs and would create
    # circular reinforcement.  It remains available in the audit payload only.

    learning = item.get("v32_learning") or {}
    long_adj = safe_float(learning.get("long_adjustment"), 0.0)
    short_adj = safe_float(learning.get("short_adjustment"), 0.0)
    learn_lean = clamp((long_adj - short_adj) / 8.0, -1.0, 1.0)
    votes["learning_v32"] = {
        "lean": learn_lean,
        "confidence": clamp(abs(learn_lean), 0.0, 1.0),
        "side": "LONG" if learn_lean > 0.12 else "SHORT" if learn_lean < -0.12 else "WAIT",
        "raw": {"long_adj": long_adj, "short_adj": short_adj},
        "label": "یادگیری تاریخی",
    }

    ai = item.get("ai_ensemble") or item.get("ai_opinions") or (item.get("edge") or {}).get("ai") or {}
    ai_side = str(ai.get("majority") or ai.get("side") or item.get("ai_majority") or "WAIT").upper()
    if ai_side in {"صعودی", "BUY", "LONG"}:
        a_lean, a_side = 0.5, "LONG"
    elif ai_side in {"نزولی", "SELL", "SHORT"}:
        a_lean, a_side = -0.5, "SHORT"
    else:
        a_lean, a_side = 0.0, "WAIT"
    a_conf = clamp(safe_float(ai.get("agreement"), 0.0) / 100.0, 0.0, 1.0)
    votes["ai_vote"] = {
        "lean": a_lean, "confidence": max(a_conf, 0.15 if a_side != "WAIT" else 0.05),
        "side": a_side, "raw": ai_side, "label": "رأی AI",
    }

    dq = item.get("data_quality") or {}
    trust = safe_float(dq.get("score"), safe_float(item.get("data_trust"), safe_float(item.get("trust_index"), 70.0)))
    votes["data_trust"] = {
        "lean": 0.0, "confidence": clamp(trust / 100.0, 0.0, 1.0),
        "side": "WAIT", "raw": trust, "label": "اعتماد داده", "trust": trust,
    }
    return votes


def _central_decide(item: dict[str, Any]) -> tuple[str, dict[str, Any]]:
    votes = _central_votes(item)
    with _CENTRAL_WEIGHT_LOCK:
        weights = dict(_CENTRAL_WEIGHTS)

    long_score = short_score = weight_sum = 0.0
    details = []
    for name, v in votes.items():
        if name == "data_trust":
            continue
        w = safe_float(weights.get(name), 1.0)
        lean = safe_float(v.get("lean"), 0.0)
        conf = safe_float(v.get("confidence"), 0.0)
        effective = w * conf
        weight_sum += effective
        if lean > 0:
            long_score += effective * lean
        elif lean < 0:
            short_score += effective * abs(lean)
        details.append({
            "component": name, "label": v.get("label"), "side": v.get("side"),
            "lean": round(lean, 4), "confidence": round(conf, 4), "weight": round(w, 4),
            "contribution": round(effective * lean, 4), "raw": v.get("raw"),
        })
    if weight_sum > 0:
        long_score /= weight_sum
        short_score /= weight_sum

    trust = safe_float((votes.get("data_trust") or {}).get("trust"), 70.0)
    margin = abs(long_score - short_score)
    edge = max(long_score, short_score)
    reasons: list[str] = []
    candidate = "LONG" if long_score > short_score else "SHORT" if short_score > long_score else "WAIT"

    overlap = _edge_overlap_gate(_normalize_symbol(item.get("symbol") or ""), candidate)
    if candidate in {"LONG", "SHORT"} and not overlap.get("ok", True):
        reasons.append(str(overlap.get("reason") or "overlap risk"))
        candidate = "WAIT"

    price = safe_float(str(item.get("price_raw") or item.get("live_price") or item.get("price") or "0").replace(",", ""), 0.0)
    if price <= 0:
        reasons.append("قیمت نامعتبر")
    if trust < _CENTRAL_MIN_TRUST:
        reasons.append(f"اعتماد داده پایین ({trust:.0f})")
    if edge < _CENTRAL_MIN_EDGE:
        reasons.append(f"لبه تصمیم ناکافی ({edge:.3f})")
    if margin < _CENTRAL_MIN_MARGIN:
        reasons.append(f"حاشیه LONG/SHORT کم ({margin:.3f})")

    htf_side = str((votes.get("htf_trend") or {}).get("side") or "WAIT")
    htf_conf = safe_float((votes.get("htf_trend") or {}).get("confidence"), 0)
    if candidate == "LONG" and htf_side == "SHORT" and htf_conf >= 0.35:
        reasons.append("روند کلان مخالف لانگ")
        candidate = "WAIT"
    if candidate == "SHORT" and htf_side == "LONG" and htf_conf >= 0.35:
        reasons.append("روند کلان مخالف شورت")
        candidate = "WAIT"

    # Level integrity / rebuild
    rr1 = safe_float(item.get("rr_tp1"), 0.0)
    if candidate in {"LONG", "SHORT"} and price > 0:
        sl = safe_float(str(item.get("stop_loss") or "0").replace(",", ""), 0.0)
        tp1 = safe_float(str(item.get("tp1") or "0").replace(",", ""), 0.0)
        tp2 = safe_float(str(item.get("tp2") or "0").replace(",", ""), 0.0)
        atr = safe_float(item.get("atr"), price * 0.012) or price * 0.012
        if candidate == "LONG":
            bad = (
                sl <= 0 or tp1 <= 0 or tp2 <= 0
                or not (sl < price < tp1 < tp2)
            )
            if bad:
                sl, tp1, tp2 = price - 1.35 * atr, price + 2.3 * atr, price + 3.5 * atr
        else:
            bad = (
                sl <= 0 or tp1 <= 0 or tp2 <= 0
                or not (tp2 < tp1 < price < sl)
            )
            if bad:
                sl, tp1, tp2 = price + 1.35 * atr, price - 2.3 * atr, price - 3.5 * atr
        item["stop_loss"] = round(sl, 8)
        item["tp1"] = round(tp1, 8)
        item["tp2"] = round(tp2, 8)
        item["stop_loss_raw"] = float(sl)
        item["tp1_raw"] = float(tp1)
        item["tp2_raw"] = float(tp2)
        rr1 = abs(tp1 - price) / max(abs(price - sl), 1e-12)
        rr2 = abs(tp2 - price) / max(abs(price - sl), 1e-12)
        item["rr_tp1"] = round(rr1, 3)
        item["rr_tp2"] = round(rr2, 3)
        item["effective_rr_tp1"] = round(rr1, 3)
        item["effective_rr_tp2"] = round(rr2, 3)
        if rr1 < 1.08:
            reasons.append(f"R:R ضعیف ({rr1:.2f})")
            candidate = "WAIT"
        if candidate == "SHORT":
            if edge < _CENTRAL_MIN_EDGE_SHORT:
                reasons.append(f"لبه SHORT ناکافی ({edge:.3f})")
                candidate = "WAIT"
            if margin < _CENTRAL_MIN_MARGIN_SHORT:
                reasons.append(f"حاشیه SHORT کم ({margin:.3f})")
                candidate = "WAIT"

    decision = candidate if not reasons and candidate in {"LONG", "SHORT"} else "WAIT"
    if decision in {"LONG", "SHORT"}:
        reasons.append("داور مرکزی: اجماع وزنی شواهد کافی است")
    elif not reasons:
        reasons.append("شواهد برای ورود جهت‌دار کافی نیست")

    conf100 = clamp(50.0 + edge * 40.0 + margin * 25.0 + (trust - 50.0) * 0.15, 5.0, 92.0)
    if decision == "WAIT":
        conf100 = min(conf100, 55.0)

    scorecard = []
    for d in details:
        aligned = decision != "WAIT" and d["side"] == decision
        opposed = decision != "WAIT" and d["side"] in {"LONG", "SHORT"} and d["side"] != decision
        scorecard.append({**d, "aligned": aligned, "opposed": opposed,
                          "preview": "reward" if aligned else "penalty" if opposed else "neutral"})

    meta = {
        "version": TITAN_CENTRAL_VERSION,
        "decision": decision,
        "long_score": round(long_score, 5),
        "short_score": round(short_score, 5),
        "edge": round(edge, 5),
        "margin": round(margin, 5),
        "confidence": round(conf100, 2),
        "trust": round(trust, 2),
        "rr1": round(rr1, 3),
        "reasons": reasons,
        "components": scorecard,
        "weights": {k: round(v, 4) for k, v in weights.items()},
        "entry_quality": round(clamp((edge * 45.0 + margin * 30.0 + trust * 0.25), 0.0, 100.0), 2),
        "directional_bias": round((long_score - short_score) * 100.0, 2),
        "overlap": overlap,
        "authoritative": True,
        "timestamp": time.time(),
    }
    return decision, meta



def _real_edge_engine(item: dict[str, Any], decision: str, meta: dict[str, Any]) -> tuple[str, dict[str, Any]]:
    """Final real-edge gate: regime + structure + liquidity + MTF + entry + risk.

    This layer is deliberately conservative.  It does not invent probability;
    it can only confirm an existing directional candidate or demote it to WAIT.
    """
    x = item or {}
    d = str(decision or "WAIT").upper()
    price = safe_float(x.get("price_raw"), 0.0)
    atr = safe_float(x.get("atr"), 0.0)
    regime = x.get("regime") if isinstance(x.get("regime"), dict) else {}
    structure = x.get("structure") if isinstance(x.get("structure"), dict) else {}
    liquidity = x.get("liquidity") if isinstance(x.get("liquidity"), dict) else {}
    precision = x.get("precision") if isinstance(x.get("precision"), dict) else {}
    fusion = x.get("fusion") if isinstance(x.get("fusion"), dict) else {}
    tf = x.get("tf_results") if isinstance(x.get("tf_results"), dict) else {}

    reg_name = str(regime.get("regime") or "unknown").lower()
    reg_conf = clamp(safe_float(regime.get("confidence"), 0), 0, 100)
    struct_event = str(structure.get("event") or "UNKNOWN").upper()
    struct_conf = clamp(safe_float(structure.get("confirmation_score"), 0), 0, 100)
    liq_pressure = safe_float(liquidity.get("pressure"), 0)
    liq_bias = str(liquidity.get("liquidity_bias") or "unknown").lower()
    precision_score = clamp(safe_float(precision.get("score"), 50), 0, 100)
    alignment = clamp(safe_float(x.get("alignment"), safe_float(meta.get("alignment"), 50)), 0, 100)

    # 1) True trend/regime compatibility.
    if d == "LONG":
        regime_side_ok = reg_name in {"trend_up", "breakout_watch"} or "up" in reg_name
        structure_ok = struct_event in {"BOS_UP", "BULL_STRUCTURE"}
        flow_ok = liq_pressure >= -0.05
    elif d == "SHORT":
        regime_side_ok = reg_name in {"trend_down", "breakout_watch"} or "down" in reg_name
        structure_ok = struct_event in {"BOS_DOWN", "BEAR_STRUCTURE"}
        flow_ok = liq_pressure <= 0.05
    else:
        regime_side_ok = structure_ok = flow_ok = False

    # 2) Multi-timeframe alignment: use existing per-TF evidence when present.
    tf_sides=[]
    for key,val in tf.items():
        if isinstance(val, dict):
            side=str(val.get("side") or val.get("bias") or "").upper()
            if side in {"LONG","SHORT"}: tf_sides.append(side)
    if tf_sides and d in {"LONG","SHORT"}:
        aligned_n=sum(1 for side in tf_sides if side==d)
        mtf_pct=aligned_n/max(1,len(tf_sides))*100.0
    else:
        mtf_pct=alignment

    # 3) Dynamic entry zone.  Current live price is the anchor; the zone is not
    # a promise of fill, it is a bounded pullback/confirmation area.
    if price > 0 and atr > 0:
        zone_width=max(price*0.0012, atr*0.30)
        if d == "LONG":
            entry_low, entry_high = price-zone_width, price+zone_width*0.20
        elif d == "SHORT":
            entry_low, entry_high = price-zone_width*0.20, price+zone_width
        else:
            entry_low, entry_high = price-zone_width, price+zone_width
    else:
        zone_width=0.0; entry_low=entry_high=price

    overextended = "overextended_entry" in [str(v) for v in (precision.get("hard_blocks") or [])]
    if price > 0 and atr > 0:
        vwap=safe_float(x.get("vwap"), price)
        stretch_atr=abs(price-vwap)/atr if vwap > 0 else 0.0
    else:
        stretch_atr=0.0
    entry_state="OPTIMAL"
    if overextended or stretch_atr > 2.2:
        entry_state="LATE"
    elif stretch_atr > 1.25:
        entry_state="EARLY/EXTENDED"

    # 4) Risk/exit integrity.
    sl=safe_float(x.get("stop_loss_raw"), safe_float(x.get("stop_loss"), 0))
    tp1=safe_float(x.get("tp1_raw"), safe_float(x.get("tp1"), 0))
    tp2=safe_float(x.get("tp2_raw"), safe_float(x.get("tp2"), 0))
    risk_dist=abs(price-sl) if price>0 and sl>0 else 0.0
    rr1=abs(tp1-price)/max(risk_dist,1e-12) if risk_dist else 0.0
    rr2=abs(tp2-price)/max(risk_dist,1e-12) if risk_dist else 0.0
    level_ok=(d=="LONG" and sl<price<tp1<tp2) or (d=="SHORT" and tp2<tp1<price<sl)

    # 5) Correlation/portfolio concentration already maintained by overlap gate;
    # surface its live state rather than hiding it.
    corr=fusion.get("btc_correlation") if isinstance(fusion.get("btc_correlation"),dict) else {}
    corr_blocked=bool(corr.get("blocked") or corr.get("veto"))

    # 6) No-trade intelligence: reasons are explicit and auditable.
    blocks=[]
    if d in {"LONG","SHORT"}:
        if not regime_side_ok: blocks.append("regime_conflict")
        if not structure_ok: blocks.append("structure_not_confirmed")
        if mtf_pct < 55: blocks.append("mtf_alignment_low")
        if struct_conf < 48: blocks.append("structure_confidence_low")
        if reg_conf < 45: blocks.append("regime_confidence_low")
        if not flow_ok: blocks.append("liquidity_flow_conflict")
        if corr_blocked: blocks.append("correlation_risk")
        if overextended or entry_state == "LATE": blocks.append("late_entry")
        if not level_ok: blocks.append("invalid_levels")
        if rr1 < 1.10 or rr2 < 1.40: blocks.append("weak_rr")
        if precision_score < 44: blocks.append("entry_quality_low")

    # 7) Composite quality.  This is a quality score, NOT a win probability.
    regime_component=reg_conf if regime_side_ok else max(0.0, reg_conf-35)
    structure_component=struct_conf if structure_ok else max(0.0, struct_conf-30)
    liquidity_component=50 + liq_pressure*200
    liquidity_component=clamp(liquidity_component if d=="LONG" else 100-liquidity_component,0,100)
    rr_component=clamp(50 + (rr1-1)*20 + (rr2-1.5)*10,0,100)
    real_quality=clamp(
        regime_component*0.20 + structure_component*0.22 + mtf_pct*0.18
        + precision_score*0.18 + liquidity_component*0.10 + rr_component*0.12,
        0,100)
    if d=="WAIT": real_quality=min(real_quality,55)

    # 8) Path simulation is a transparent ATR/level proxy, never labeled as realized.
    expected_mae_r=0.65 if atr>0 else None
    expected_mfe_r=rr2 if rr2>0 else None
    path_quality=clamp((safe_float(expected_mfe_r,0)/max(safe_float(expected_mae_r,1),1e-9))*30,0,100) if expected_mfe_r else 0

    # 9) Conservative final gate. Existing Central Governor remains authoritative;
    # this layer only demotes a candidate when the evidence is materially unsafe.
    final=d
    min_q = 58.0 if d == "SHORT" else 55.0
    if d in {"LONG","SHORT"} and (blocks or real_quality < min_q):
        final="WAIT"
    if final != d and d in {"LONG","SHORT"}:
        blocks.append("REAL_EDGE_FINAL_GATE")

    lifecycle="WAITING_ENTRY" if final in {"LONG","SHORT"} and entry_state!="OPTIMAL" else "READY" if final in {"LONG","SHORT"} else "NO_TRADE"
    return final, {
        "version":"V30-REAL-EDGE",
        "direction":final,
        "candidate_direction":d,
        "regime":reg_name,
        "regime_confidence":round(reg_conf,1),
        "structure_event":struct_event,
        "structure_confidence":round(struct_conf,1),
        "mtf_alignment_pct":round(mtf_pct,1),
        "liquidity_bias":liq_bias,
        "liquidity_pressure":round(liq_pressure,4),
        "entry_quality":round(precision_score,1),
        "entry_zone":{"low":round(entry_low,8),"high":round(entry_high,8),"width":round(zone_width,8)},
        "entry_state":entry_state,
        "rr_tp1":round(rr1,3),"rr_tp2":round(rr2,3),"levels_valid":bool(level_ok),
        "correlation":corr,
        "real_edge_quality":round(real_quality,1),
        "path_quality":round(path_quality,1),
        "expected_mae_r_proxy":expected_mae_r,
        "expected_mfe_r_proxy":round(expected_mfe_r,3) if expected_mfe_r is not None else None,
        "no_trade_reasons":blocks,
        "lifecycle":lifecycle,
        "probability_note":"کیفیت تصمیم است، نه احتمال برد؛ probability فقط از calibration realized استفاده می‌شود.",
        "champion_challenger":"shadow_only_until_OOS_validation",
        "signal_invalidation":"ساختار/رژیم/سطح حدضرر نقض شود یا قیمت خارج از منطق ورود شود.",
    }

def _central_seal(item: dict[str, Any]) -> dict[str, Any]:
    x = dict(item or {})
    # refresh live price if possible
    try:
        sym = str(x.get("symbol") or "")
        with LIVE_LOCK:
            info = LIVE_PRICES.get(_normalize_symbol(sym)) or {}
        live_px = safe_float(info.get("price"), 0.0)
        if live_px > 0:
            x["price_raw"] = live_px
            x["live_price"] = live_px
            x["entry_raw"] = live_px
            x["price"] = smart_format(live_px)
            x["entry_valid"] = smart_format(live_px)
            age = time.time() - safe_float(info.get("ts"), time.time())
            x["live_price_age_sec"] = round(age, 2)
    except Exception:
        _swallow()

    decision, meta = _central_decide(x)
    # V30 Real Edge Engine: final quality/no-trade gate. It never creates a
    # direction from nothing; it only confirms or demotes the Central decision.
    try:
        edge_decision, edge_pack = _real_edge_engine(x, decision, meta)
        if edge_decision != decision:
            meta = dict(meta)
            meta.setdefault("reasons", [])
            meta["reasons"] = list(meta.get("reasons") or []) + [
                "V30 REAL EDGE: " + ", ".join(edge_pack.get("no_trade_reasons") or ["quality_gate"])
            ]
            meta["entry_quality"] = edge_pack.get("real_edge_quality", meta.get("entry_quality", 50))
            meta["real_edge"] = edge_pack
            meta["decision_before_real_edge"] = decision
            decision = edge_decision
        else:
            meta = dict(meta)
            meta["real_edge"] = edge_pack
            meta["entry_quality"] = edge_pack.get("real_edge_quality", meta.get("entry_quality", 50))
    except Exception as _re_exc:
        LOGGER.debug("V30 real edge gate failed: %s", _re_exc)
        meta = dict(meta)
        meta["real_edge"] = {"version":"V30-REAL-EDGE","status":"degraded","error":str(_re_exc)[:180]}
    bias = "صعودی" if decision == "LONG" else "نزولی" if decision == "SHORT" else "خنثی"
    x["decision"] = decision
    x["decision_tag"] = decision
    x["bias"] = bias
    x["entry_mode"] = "EARLY" if decision in {"LONG", "SHORT"} else "WAIT"
    x["signal_tag"] = f"CENTRAL — {decision}"
    x["decision_state"] = f"CENTRAL_{decision}"
    x["authority"] = TITAN_CENTRAL_VERSION
    x["architecture"] = "SINGLE_CENTRAL_GOVERNOR"
    conf = safe_float(meta.get("confidence"), 50.0)
    x["decision_confidence"] = conf
    # This number is a model-confidence proxy, not a calibrated probability
    # of profit.  Keep the legacy fields for dashboard compatibility but expose
    # the distinction explicitly so users do not read 80 as "80% win chance".
    cal_pack = _edge_calibrate_central(conf, str(decision), str(x.get("symbol") or ""))
    x["calibrated_probability"] = cal_pack.get("calibrated")
    x["success_prob"] = conf
    x["success_probability"] = safe_float(cal_pack.get("calibrated"), conf)
    x["success_probability_is_calibrated"] = bool(cal_pack.get("is_calibrated"))
    x["probability_calibration"] = cal_pack
    x["entry_quality"] = safe_float(meta.get("entry_quality"), 50.0)
    x["directional_bias"] = safe_float(meta.get("directional_bias"), 0.0)
    x["edge_lab_version"] = EDGE_LAB_VERSION
    x["central_decision"] = meta
    x["decision_reasons"] = list(meta.get("reasons") or [])
    x["central_reason_fa"] = " · ".join(x["decision_reasons"][:4])
    x["decision_architecture"] = {
        "type": "SINGLE_CENTRAL_GOVERNOR",
        "authoritative_source": TITAN_CENTRAL_VERSION,
        "final_decision": decision,
        "legacy_engines_are_evidence_only": True,
    }
    for key in ("canonical_decision", "v32_decision", "v31_decision", "arbiter_verdict"):
        prev = x.get(key)
        if isinstance(prev, dict):
            prev = dict(prev)
            prev["decision"] = decision
            prev["overridden_by"] = TITAN_CENTRAL_VERSION
            x[key] = prev
    return x


def _central_record_prediction(item: dict[str, Any]) -> None:
    """Persist only independent directional observations.

    A scan can run every ~45s, but the same setup must not become dozens of
    pseudo-samples.  WAIT is kept in the arbiter log for auditability, while
    only LONG/SHORT observations enter the learning dataset with a cooldown.
    """
    try:
        meta = item.get("central_decision") or {}
        decision = str(item.get("decision_tag") or "WAIT").upper()
        symbol = _normalize_symbol(item.get("symbol") or "")
        now = time.time()

        with DB_LOCK, db_conn() as con:
            # V45: one arbiter row per symbol/decision per 30s (scan + live refresh used to double-write).
            _v45_dup = con.execute(
                "SELECT 1 FROM central_arbiter_log WHERE symbol=? AND decision=? AND created_at>? LIMIT 1",
                (symbol, decision, now - 30)).fetchone()
            if not _v45_dup:
                con.execute(
                    """INSERT INTO central_arbiter_log(created_at,symbol,decision,verdict,score,notes)
                       VALUES(?,?,?,?,?,?)""",
                    (
                        now, symbol, decision,
                        "ACCEPT" if decision in {"LONG", "SHORT"} else "WAIT",
                        safe_float(meta.get("confidence"), 0.0),
                        " · ".join((meta.get("reasons") or [])[:4]),
                    ),
                )

            # Learning samples must represent distinct setups, not scan frequency.
            if decision not in {"LONG", "SHORT"}:
                con.commit()
                return

            recent = con.execute(
                """SELECT 1 FROM central_predictions
                   WHERE symbol=? AND created_at>=?
                   LIMIT 1""",
                (symbol, now - SIGNAL_COOLDOWN_SECONDS),
            ).fetchone()
            if recent:
                con.commit()
                return

            con.execute(
                """INSERT INTO central_predictions(
                    created_at,symbol,decision,bias,price,stop_loss,tp1,tp2,confidence,score,margin,
                    reasons_json,components_json,weights_json,horizon_minutes,outcome,version)
                   VALUES(?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?)""",
                (
                    now,
                    symbol,
                    decision,
                    item.get("bias"),
                    safe_float(item.get("price_raw"), safe_float(str(item.get("price") or "0").replace(",", ""), 0.0)),
                    safe_float(item.get("stop_loss_raw"), safe_float(str(item.get("stop_loss") or "0").replace(",", ""), 0.0)) or None,
                    safe_float(item.get("tp1_raw"), safe_float(str(item.get("tp1") or "0").replace(",", ""), 0.0)) or None,
                    safe_float(item.get("tp2_raw"), safe_float(str(item.get("tp2") or "0").replace(",", ""), 0.0)) or None,
                    safe_float(meta.get("confidence"), 0.0),
                    safe_float(item.get("score"), 50.0),
                    safe_float(meta.get("margin"), 0.0),
                    json.dumps(meta.get("reasons") or [], ensure_ascii=False),
                    json.dumps(meta.get("components") or [], ensure_ascii=False, default=str),
                    json.dumps(meta.get("weights") or {}, ensure_ascii=False),
                    240,
                    "PENDING",
                    TITAN_CENTRAL_VERSION,
                ),
            )
            con.commit()
    except Exception as exc:
        LOGGER.debug("central record: %s", exc)


def _central_evaluate_pending_base() -> dict[str, Any]:
    """Evaluate predictions only inside their original, exact forward horizon.

    The old evaluator fetched the latest candles after the horizon and therefore
    could accidentally judge a 4-hour prediction using price action from much
    later.  It also used max/min over the whole window, which cannot tell which
    barrier was touched first.  This version uses a bounded OHLC window and the
    same chronological first-touch logic used by paper trades.
    """
    done = 0
    try:
        now = time.time()
        with DB_LOCK, db_conn() as con:
            rows = con.execute(
                """SELECT id,created_at,symbol,decision,price,stop_loss,tp1,tp2,
                          horizon_minutes,components_json,confidence
                   FROM central_predictions
                   WHERE outcome='PENDING' AND created_at<=?
                   ORDER BY created_at LIMIT 200""",
                (now - 60,),
            ).fetchall()

        for row in rows:
            (rid, created, symbol, decision, entry, sl, tp1, tp2,
             horizon, comp_json, prediction_confidence) = row
            created = float(created)
            horizon = int(horizon or 240)
            horizon_end = created + horizon * 60.0
            if now < horizon_end:
                continue

            entry = safe_float(entry, 0.0)
            if entry <= 0 or decision not in {"LONG", "SHORT"}:
                continue

            start_ms = int(created * 1000)
            end_ms = int(horizon_end * 1000)

            try:
                bars_needed = max(20, min(1000, int(math.ceil(horizon / 15.0)) + 4))
                df = fetch_klines(
                    str(symbol), "15m", bars_needed,
                    start_ms=start_ms, end_ms=end_ms,
                )
                if df is None or df.empty or "t" not in df.columns:
                    continue
                window = df[
                    (df["t"].astype(float) >= start_ms) &
                    (df["t"].astype(float) < end_ms)
                ].sort_values("t")
                if window.empty:
                    continue
            except Exception as exc:
                LOGGER.debug("central horizon fetch failed #%s: %s", rid, exc)
                continue

            # Chronological barrier evaluation.  If SL and TP are both inside
            # one OHLC candle, ordering is unknowable at this timeframe; do not
            # manufacture a WIN/LOSS sample from ambiguous data.
            touch, hit_type, exit_px = _first_touch_ohlc(
                window, decision,
                safe_float(sl, np.nan),
                safe_float(tp1, np.nan),
                safe_float(tp2, np.nan),
            )

            last = safe_float(window["close"].iloc[-1], entry)
            if decision == "LONG":
                ret = (last / entry - 1.0) * 100.0
            else:
                ret = (entry / last - 1.0) * 100.0 if last > 0 else 0.0

            if touch == "WIN":
                outcome = "WIN"
            elif touch == "LOSS":
                outcome = "LOSS"
            elif touch == "AMBIGUOUS":
                outcome = "AMBIGUOUS"
            else:
                # No barrier was touched inside the declared horizon.  This is
                # a time-expiry observation, not a binary WIN/LOSS training label.
                outcome = "TIME_EXIT"

            lesson = {
                "WIN": "اولین لمس هدف داخل پنجره پیش‌بینی رخ داد.",
                "LOSS": "اولین لمس حد ضرر داخل پنجره پیش‌بینی رخ داد.",
                "AMBIGUOUS": "حد ضرر و هدف در یک کندل لمس شدند؛ ترتیب قابل تشخیص نیست.",
                "TIME_EXIT": "هیچ سطحی تا پایان افق لمس نشد؛ نمونه برای یادگیری دودویی استفاده نمی‌شود.",
            }.get(outcome, "")

            # Edge Lab telemetry: MAE/MFE, time-to-event, realized regime and friction-aware R.
            regime_name, vol_pct, trend_strength = _edge_regime_from_window(window)
            mae_pct = mfe_pct = 0.0
            try:
                highs = window["high"].astype(float); lows = window["low"].astype(float)
                if decision == "LONG":
                    mae_pct = (float(lows.min()) / entry - 1.0) * 100.0
                    mfe_pct = (float(highs.max()) / entry - 1.0) * 100.0
                else:
                    mae_pct = (entry / float(highs.max()) - 1.0) * 100.0
                    mfe_pct = (entry / float(lows.min()) - 1.0) * 100.0
            except Exception:
                _swallow()
            touch_d, touch_px, touch_ts = _edge_first_touch_detail(window, decision, safe_float(sl,np.nan), safe_float(tp1,np.nan), safe_float(tp2,np.nan))
            event_time = ((touch_ts - created) / 60.0) if touch_ts is not None else float(horizon)
            friction_pct = TOTAL_ENTRY_BUFFER * 2.0 * 100.0
            gross_ret = ret
            net_ret = gross_ret - friction_pct if math.isfinite(gross_ret) else gross_ret
            risk_dist = abs(entry - safe_float(sl, entry))
            r_mult = ((touch_px-entry)/max(risk_dist,1e-12) if decision=="LONG" and touch_px else (entry-touch_px)/max(risk_dist,1e-12) if decision=="SHORT" and touch_px else net_ret/max((risk_dist/max(entry,1e-12))*100.0,1e-12))
            entry_quality = clamp(50.0 + abs(safe_float(prediction_confidence,50.0)-50.0)*0.6 + trend_strength*0.2, 0.0, 100.0)
            directional_bias = 100.0 if decision=="LONG" else -100.0
            with DB_LOCK, db_conn() as con:
                con.execute("INSERT OR REPLACE INTO central_trade_metrics(prediction_id,regime,volatility_pct,trend_strength,mae_pct,mfe_pct,time_to_event_min,exit_price,net_return_pct,r_multiple,entry_quality,directional_bias,ambiguity,friction_pct,evaluated_at,param_version,edge_lab_version) VALUES(?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?)",
                            (rid,regime_name,vol_pct,trend_strength,mae_pct,mfe_pct,event_time,touch_px or last,net_ret,r_mult,entry_quality,directional_bias,1 if outcome=="AMBIGUOUS" else 0,friction_pct,now,TITAN_PARAM_VERSION,EDGE_LAB_VERSION))
                con.commit()

            try:
                comps = json.loads(comp_json or "[]")
            except Exception:
                comps = []

            # Only unambiguous barrier outcomes are allowed to change weights.
            if outcome in {"WIN", "LOSS"} and isinstance(comps, list):
                for c in comps:
                    name = str(c.get("component") or "")
                    if not name or name not in _CENTRAL_WEIGHTS_DEFAULT:
                        continue
                    side = str(c.get("side") or "WAIT")
                    aligned = side == decision
                    win = outcome == "WIN"
                    reward = (
                        1.0 if (win and aligned)
                        else 0.5 if ((not win) and side in {"LONG", "SHORT"} and not aligned)
                        else 0.0
                    )
                    penalty = (
                        1.0 if ((not win) and aligned)
                        else 0.5 if (win and side in {"LONG", "SHORT"} and not aligned)
                        else 0.0
                    )
                    with DB_LOCK, db_conn() as con:
                        con.execute(
                            """INSERT INTO central_component_stats(
                               component,samples,wins,losses,reward_sum,penalty_sum,weight,updated_at)
                               VALUES(?,?,?,?,?,?,?,?)
                               ON CONFLICT(component) DO UPDATE SET
                                 samples=samples+1,
                                 wins=wins+excluded.wins,
                                 losses=losses+excluded.losses,
                                 reward_sum=reward_sum+excluded.reward_sum,
                                 penalty_sum=penalty_sum+excluded.penalty_sum,
                                 updated_at=excluded.updated_at""",
                            (
                                name, 1,
                                1 if (win and aligned) else 0,
                                1 if ((not win) and aligned) else 0,
                                reward, penalty,
                                safe_float(_CENTRAL_WEIGHTS_DEFAULT.get(name), 1.0),
                                now,
                            ),
                        )

            with DB_LOCK, db_conn() as con:
                con.execute(
                    """UPDATE central_predictions
                       SET outcome=?,evaluated_at=?,return_pct=?,lesson=?
                       WHERE id=?""",
                    (outcome, now, ret, lesson, rid),
                )
                con.commit()
            done += 1

        if done:
            _central_load_weights()
        return {"ok": True, "evaluated": done}
    except Exception as exc:
        LOGGER.debug("central evaluate: %s", exc)
        return {"ok": False, "error": str(exc)[:200]}

def _emergency_live_cards(coins: list | None = None) -> list[dict[str, Any]]:
    """Never leave Android dashboard blank — live prices + WAIT."""
    coins = list(coins or USER_SETTINGS.get("active_coins") or DEFAULT_COINS)
    cards: list[dict[str, Any]] = []
    prices: dict[str, float] = {}
    try:
        prices = dict(_fetch_live_prices(list(coins)) or {})
    except Exception as exc:
        LOGGER.warning("emergency prices: %s", exc)
    now = time.time()
    for sym in coins:
        px = safe_float(prices.get(sym), 0.0)
        if px <= 0:
            for k, v in prices.items():
                if _normalize_symbol(k) == _normalize_symbol(sym):
                    px = safe_float(v, 0.0)
                    break
        if px <= 0:
            continue
        base = sym.split("/")[0] if "/" in sym else sym
        meta = COIN_META.get(base, (base, "●"))
        cards.append({
            "symbol": sym,
            "base_symbol": base,
            "coin_name": meta[0],
            "coin_icon": meta[1] if len(meta) > 1 else "●",
            "name": meta[0],
            "icon": meta[1] if len(meta) > 1 else "●",
            "tv_symbol": _binance_symbol(sym),
            "price": smart_format(px), "price_raw": px, "live_price": px,
            "entry_raw": px, "entry_valid": smart_format(px),
            "decision": "WAIT", "decision_tag": "WAIT", "bias": "خنثی",
            "score": 50, "score_bar": 50, "score_color": "#94a3b8",
            "signal_quality": 40, "alignment": 50,
            "success_probability": 50, "success_prob": 50, "trust_index": 40,
            "stop_loss": "—", "tp1": "—", "tp2": "—", "rr_tp1": "—",
            "authority": TITAN_CENTRAL_VERSION,
            "signal_tag": "LIVE-PRICE ONLY · WAIT",
            "central_reason_fa": "اسکن کامل در حال اجرا؛ فقط قیمت زنده",
            "scan_timestamp": now, "emergency_card": True,
            "tfs": {"15m": 50.0, "1h": 50.0, "4h": 50.0, "1d": 50.0},
            "tf_scores": {"15m": 50.0, "1h": 50.0, "4h": 50.0, "1d": 50.0},
            "ai_opinions": {
                "providers": [],
                "internal": "قیمت زنده · تحلیل کامل در صف",
                "titan": "قیمت زنده · تحلیل کامل در صف",
                "ai_status": {
                    "gemini": "در صف تحلیل پس‌زمینه",
                    "openai": "در انتظار تحلیل",
                    "grok": "در انتظار تحلیل",
                    "claude": "در انتظار تحلیل",
                    "deepseek": "در انتظار تحلیل",
                },
            },
        })
    return cards



# ============================================================
# TITAN V31 ADVANCED EDGE SUITE — 21 production modules
# Research/decision-support only. No order execution.
# ============================================================
V31_EDGE_VERSION = "TITAN-V31-21-EDGE-SUITE"
_V31_MEMORY = {}
_V31_LOCK = threading.RLock()


def _v31_num(x, default=0.0):
    try:
        v=float(x)
        return default if not math.isfinite(v) else v
    except Exception:
        return default


def _v31_side(item):
    d=str(item.get("decision_tag") or item.get("decision") or "WAIT").upper()
    return d if d in {"LONG","SHORT"} else "WAIT"

# 1) Signal DNA: immutable snapshot of the setup, so every realized result is attributable.
def _v31_signal_dna(item):
    side=_v31_side(item); r=_v31_num(item.get("rsi"),50); score=_v31_num(item.get("score"),50)
    return {"side":side,"score":round(score,2),"rsi":round(r,2),
            "regime":(item.get("regime") or item.get("market_regime") or "unknown"),
            "structure":(item.get("structure") or {}).get("bias", item.get("structure_bias","unknown")) if isinstance(item.get("structure"),dict) else item.get("structure_bias","unknown"),
            "entry":_v31_num(item.get("price") or item.get("entry_raw")),
            "rr1":_v31_num(item.get("rr_tp1")),"rr2":_v31_num(item.get("rr_tp2")),
            "quality":_v31_num(item.get("signal_quality"),0),"timestamp":time.time()}

# 2) Evidence fusion: correlated evidence is discounted; independent evidence is rewarded.
def _v31_evidence_fusion(item):
    dna=_v31_signal_dna(item); side=dna["side"]
    raw=[]
    for k,v in ((item.get("fusion") or {}).items() if isinstance(item.get("fusion"),dict) else []):
        if isinstance(v,(int,float)): raw.append((k,float(v)))
    support=[]
    if side=="LONG": support=[_v31_num(item.get("score"),50)/100,_v31_num(item.get("alignment"),50)/100]
    elif side=="SHORT": support=[1-_v31_num(item.get("score"),50)/100,1-_v31_num(item.get("alignment"),50)/100]
    else: support=[.5]
    # two strong but dependent price-derived signals never count as two full independent votes.
    independent=min(1.0,0.55*max(support)+0.45*(sum(support)/len(support)))
    return {"independence_score":round(independent,4),"raw_components":len(raw),"discount":round(1.0-0.35*max(0,len(raw)-3)/max(1,len(raw)),4)}

# 3) Counterfactual engine: explicit reasons the thesis can fail.
def _v31_counterfactual(item):
    side=_v31_side(item); score=_v31_num(item.get("score"),50); rr=_v31_num(item.get("rr_tp1"),0)
    risks=[]
    if side=="LONG" and score<55: risks.append("جهت صعودی ضعیف")
    if side=="SHORT" and score>45: risks.append("جهت نزولی ضعیف")
    if rr and rr<0.9: risks.append("R/R ضعیف")
    if str(item.get("regime") or "").lower() in {"transition","shock","unknown"}: risks.append("رژیم ناپایدار")
    return {"failure_risks":risks,"counterfactual_score":round(max(0,100-20*len(risks)),1),"thesis_fragile":len(risks)>=2}

# 4) Adversarial robustness: deterministic perturbation envelope, not a fake Monte-Carlo forecast.
def _v31_adversarial(item):
    q=_v31_num(item.get("signal_quality"),50); rr=_v31_num(item.get("rr_tp1"),1.0); side=_v31_side(item)
    if side=="WAIT": return {"robustness":50.0,"stress_cases":0,"failures":0}
    cases=[q-5,q-10,q-15, q-(2 if rr<1.2 else 0)]
    failures=sum(x<45 for x in cases)
    return {"robustness":round(max(0,min(100,100-15*failures-5*max(0,1.0-rr))),1),"stress_cases":len(cases),"failures":failures}

# 5) Entry stability: small price perturbations must not flip the thesis.
def _v31_entry_stability(item):
    p=_v31_num(item.get("price") or item.get("entry_raw")); sl=_v31_num(item.get("stop_loss")); tp=_v31_num(item.get("tp1")); side=_v31_side(item)
    if not p or side=="WAIT": return {"score":50.0,"band_pct":0.0}
    band=0.0025; vals=[]
    for f in (1-band,1-band/2,1,1+band/2,1+band):
        ep=p*f
        if side=="LONG": vals.append(float(sl<p and ep>sl and (not tp or ep<tp)))
        else: vals.append(float(sl>p and ep<sl and (not tp or ep>tp)))
    return {"score":round(100*sum(vals)/len(vals),1),"band_pct":band*100}

# 6) Exit intelligence: structure/risk/time/liquidity aware exit mode.
def _v31_exit_intelligence(item):
    side=_v31_side(item); rr1=_v31_num(item.get("rr_tp1"),0); rr2=_v31_num(item.get("rr_tp2"),0)
    regime=str(item.get("regime") or "").lower(); mode="HOLD_TO_TARGET"
    if side=="WAIT": mode="NONE"
    elif "shock" in regime: mode="DEFENSIVE_REDUCE"
    elif rr1<1.0: mode="EARLY_EXIT_BIAS"
    elif rr2>=1.8: mode="RUNNER_TO_TP2"
    return {"mode":mode,"rr_tp1":rr1,"rr_tp2":rr2,"invalidation":"structure_break_or_SL"}

# 7) Confidence decay: stale evidence loses weight with time.
def _v31_confidence_decay(item):
    ts=_v31_num(item.get("scan_timestamp"),time.time()); age=max(0,time.time()-ts); half=900.0
    decay=math.exp(-math.log(2)*age/half)
    return {"age_sec":round(age,1),"decay":round(decay,4),"effective_quality":round(_v31_num(item.get("signal_quality"),0)*decay,2)}

# 8) Market shock detector: uses available live/quality features conservatively.
def _v31_shock(item):
    atr=_v31_num(item.get("atr")); vol=bool(item.get("volume_spike")); spread=_v31_num(item.get("spread_pct"),0)
    flags=[]
    if vol: flags.append("volume_spike")
    if spread>0.25: flags.append("wide_spread")
    if atr<=0: flags.append("atr_missing")
    return {"mode":"SHOCK" if len(flags)>=2 else "NORMAL","flags":flags,"severity":min(1.0,len(flags)/3)}

# 9) Asset personality: persistent in-process profile, updated from each signal DNA.
def _v31_personality(item):
    sym=str(item.get("symbol") or "UNKNOWN"); side=_v31_side(item)
    with _V31_LOCK:
        st=_V31_MEMORY.setdefault(sym,{"samples":0,"long":0,"short":0,"quality_sum":0.0})
        st["samples"]+=1; st["long"]+=int(side=="LONG"); st["short"]+=int(side=="SHORT"); st["quality_sum"]+=_v31_num(item.get("signal_quality"),0)
        return {"samples":st["samples"],"long_share":round(st["long"]/st["samples"],3),"avg_quality":round(st["quality_sum"]/st["samples"],2)}

# 10) Session intelligence: UTC session bucket is deterministic and timezone-safe.
def _v31_session(item):
    h=datetime.now(timezone.utc).hour
    bucket="ASIA" if h<8 else "EUROPE" if h<13 else "US" if h<21 else "LATE"
    return {"session":bucket,"utc_hour":h}

# 11) Regime transition detector: disagreement between current regime and prior regime is a warning.
def _v31_transition(item):
    sym=str(item.get("symbol") or "UNKNOWN"); regime=str(item.get("regime") or item.get("market_regime") or "unknown")
    with _V31_LOCK:
        prev=_V31_MEMORY.setdefault("_regime",{}).get(sym); _V31_MEMORY["_regime"][sym]=regime
    return {"transition":bool(prev and prev!=regime),"previous":prev,"current":regime}

# 12) Dead-signal detector: no meaningful movement/evidence means WAIT rather than forced action.
def _v31_dead_signal(item):
    side=_v31_side(item); q=_v31_num(item.get("signal_quality"),0); score=_v31_num(item.get("score"),50)
    dead=side=="WAIT" or q<35 or abs(score-50)<3
    return {"dead":dead,"reason":"insufficient_edge" if dead else "active_edge"}

# 13) Internal prediction market: component probabilities are combined by independent strength.
def _v31_prediction_market(item):
    score=_v31_num(item.get("score"),50)/100; align=_v31_num(item.get("alignment"),50)/100
    side=_v31_side(item)
    probs=[score,align] if side=="LONG" else [1-score,1-align] if side=="SHORT" else [.5]
    return {"probability_proxy":round(100*sum(probs)/len(probs),2),"components":len(probs),"side":side}

# 14) Bayesian updating: conservative Beta posterior from realized central samples.
def _v31_bayes(item):
    sym=str(item.get("symbol") or ""); side=_v31_side(item); wins=losses=0
    try:
        if sym and side in {"LONG","SHORT"}:
            with DB_LOCK, db_conn() as con:
                # central_predictions stores English decision tags (LONG/SHORT), not Persian bias labels.
                row=con.execute(
                    "SELECT SUM(CASE WHEN outcome='WIN' THEN 1 ELSE 0 END), "
                    "SUM(CASE WHEN outcome='LOSS' THEN 1 ELSE 0 END) "
                    "FROM central_predictions WHERE symbol=? AND decision=? AND outcome IN ('WIN','LOSS')",
                    (sym, side),
                ).fetchone()
                wins=int(row[0] or 0); losses=int(row[1] or 0)
    except Exception: _swallow()
    post=(wins+2)/(wins+losses+4)
    return {"wins":wins,"losses":losses,"posterior_pct":round(100*post,2)}

# 15) Uncertainty engine: probability and uncertainty are separate outputs.
def _v31_uncertainty(parts):
    vals=[_v31_num(parts.get("robustness"),50),_v31_num(parts.get("entry_stability"),50),_v31_num(parts.get("evidence_independence"),50)]
    uncertainty=100-sum(vals)/len(vals)
    return {"uncertainty":round(max(0,min(100,uncertainty)),2),"confidence_band":"LOW" if uncertainty<20 else "MEDIUM" if uncertainty<40 else "HIGH"}

# 16) Multi-dimensional confidence vector.
def _v31_confidence(item, parts):
    q=_v31_num(item.get("signal_quality"),0)
    return {"direction":round(abs(_v31_num(item.get("score"),50)-50)*2,1),"structure":q,"entry_quality":parts["entry_stability"],"regime":100 if not parts["transition"] else 45,"robustness":parts["robustness"],"uncertainty":parts["uncertainty"]}

# 17) Explainability: machine-readable WHY / WHY-NOT trail.
def _v31_explain(item, parts):
    why=[]; why_not=[]; side=_v31_side(item)
    if side in {"LONG","SHORT"}: why.append(f"direction={side}")
    if parts["robustness"]>=70: why.append("robust_under_stress")
    if parts["entry_stability"]>=80: why.append("stable_entry")
    if parts["transition"]: why_not.append("regime_transition")
    if parts["counterfactual"]<60: why_not.append("fragile_thesis")
    if parts["uncertainty"]>40: why_not.append("high_uncertainty")
    return {"why":why,"why_not":why_not}

# 18) Self-destruct threshold: invalidate thesis when core assumptions collapse.
def _v31_self_destruct(item, parts):
    trigger=(parts["counterfactual"]<40 or parts["robustness"]<40 or parts["dead"])
    return {"invalidate":bool(trigger),"reason":"core_edge_collapsed" if trigger else "thesis_intact"}

# 19) Data quality gate: missing core values reduce authority rather than being fabricated.
def _v31_data_quality(item):
    keys=("price","rsi","atr","score")
    missing=[k for k in keys if item.get(k) in (None,"","—")]
    score=max(0,100-20*len(missing))
    return {"score":score,"missing":missing,"gate":"PASS" if score>=80 else "DEGRADED" if score>=50 else "FAIL"}

# 20) Research lab: rolling attribution by asset/side from realized central outcomes.
def _v31_research(item):
    out={"samples":0,"wins":0,"losses":0,"win_rate":None}
    try:
        sym=str(item.get("symbol") or "")
        if sym:
            with DB_LOCK, db_conn() as con:
                r=con.execute("SELECT COUNT(*),SUM(CASE WHEN outcome='WIN' THEN 1 ELSE 0 END),SUM(CASE WHEN outcome='LOSS' THEN 1 ELSE 0 END) FROM central_predictions WHERE symbol=? AND outcome!='PENDING'",(sym,)).fetchone()
            n=int(r[0] or 0); w=int(r[1] or 0); l=int(r[2] or 0)
            out={"samples":n,"wins":w,"losses":l,"win_rate":round(100*w/n,2) if n else None}
    except Exception: _swallow()
    return out

# 21) Champion/challenger: keep the current governor authoritative; compare challengers only as audit metrics.
def _v31_champion_challenger(item, parts):
    champion=float(_v31_num(item.get("signal_quality"),0)); challenger=float((parts["robustness"]+parts["entry_stability"]+parts["counterfactual"])/3)
    return {"champion":round(champion,2),"challenger":round(challenger,2),"challenger_wins":bool(challenger>champion),"action":"AUDIT_ONLY"}


def _v31_apply(item):
    """Run all 21 modules. The suite is a safety/audit layer; it never fabricates probabilities."""
    try:
        dna=_v31_signal_dna(item); ev=_v31_evidence_fusion(item); cf=_v31_counterfactual(item); adv=_v31_adversarial(item)
        ent=_v31_entry_stability(item); ex=_v31_exit_intelligence(item); decay=_v31_confidence_decay(item); shock=_v31_shock(item)
        personality=_v31_personality(item); session=_v31_session(item); transition=_v31_transition(item); dead=_v31_dead_signal(item)
        market=_v31_prediction_market(item); bayes=_v31_bayes(item)
        unc=_v31_uncertainty({"robustness":adv["robustness"],"entry_stability":ent["score"],"evidence_independence":ev["independence_score"]*100})
        conf=_v31_confidence(item,{"entry_stability":ent["score"],"robustness":adv["robustness"],"transition":transition["transition"],"uncertainty":unc["uncertainty"]})
        explain=_v31_explain(item,{"robustness":adv["robustness"],"entry_stability":ent["score"],"transition":transition["transition"],"counterfactual":cf["counterfactual_score"],"uncertainty":unc["uncertainty"]})
        sd=_v31_self_destruct(item,{"counterfactual":cf["counterfactual_score"],"robustness":adv["robustness"],"dead":dead["dead"]})
        dq=_v31_data_quality(item); research=_v31_research(item); cc=_v31_champion_challenger(item,{"robustness":adv["robustness"],"entry_stability":ent["score"],"counterfactual":cf["counterfactual_score"]})
        # Only hard safety failures can force WAIT. This does not create a new trade signal.
        original=_v31_side(item); forced_wait=sd["invalidate"] or dq["gate"]=="FAIL" or shock["mode"]=="SHOCK"
        if forced_wait and original in {"LONG","SHORT"}:
            item["decision_tag"]="WAIT"; item["decision"]="WAIT"; item["advanced_override"]="SAFETY_WAIT"
        item["v31_edge_suite"]={"version":V31_EDGE_VERSION,"signal_dna":dna,"evidence_fusion":ev,"counterfactual":cf,"adversarial":adv,"entry_stability":ent,"exit_intelligence":ex,"confidence_decay":decay,"shock":shock,"personality":personality,"session":session,"regime_transition":transition,"dead_signal":dead,"prediction_market":market,"bayesian":bayes,"uncertainty":unc,"confidence_vector":conf,"explainability":explain,"self_destruct":sd,"data_quality":dq,"research_lab":research,"champion_challenger":cc,"safety_wait":forced_wait}
        return item
    except Exception as exc:
        LOGGER.exception("V31 edge suite failed: %s",exc)
        item["v31_edge_suite"]={"version":V31_EDGE_VERSION,"error":str(exc)[:240]}
        return item


# ============================================================
# TITAN V34 — ADAPTIVE TRUST / OPPORTUNITY / CALIBRATION CORE
# ------------------------------------------------------------
# Additive evidence layer. It does not execute trades and does not invent
# probabilities. It learns only from realized outcomes already stored by TITAN.
# Goals:
#   1) distinguish "not enough evidence" from "almost actionable"
#   2) reduce unnecessary WAIT near a coherent edge
#   3) calibrate trust using realized history with Bayesian shrinkage
#   4) adapt evidence weight by symbol/direction without overfitting
#   5) expose a transparent scorecard for performance and audit
# ============================================================
V34_VERSION = "TITAN-V34-ADAPTIVE-TRUST-OPPORTUNITY"
V34_MIN_MARGIN = 0.07
V34_PROMOTE_SCORE = 70.0
V34_MIN_DQ = 52.0
V34_MIN_QUALITY = 50.0
V34_MIN_RR = 1.10
V34_MAX_CONTRADICTION = 0.68
V34_MIN_HISTORY = 12
V34_HISTORY_SHRINK = 10.0


def _v34_history(symbol: str, side: str) -> dict[str, Any]:
    """Outcome history with Bayesian shrinkage; tiny samples never dominate."""
    wins = losses = 0
    try:
        with DB_LOCK, db_conn() as con:
            row = con.execute(
                """SELECT
                     SUM(CASE WHEN outcome='WIN' THEN 1 ELSE 0 END),
                     SUM(CASE WHEN outcome='LOSS' THEN 1 ELSE 0 END)
                   FROM central_predictions
                   WHERE symbol=? AND decision=? AND outcome IN ('WIN','LOSS')""",
                (symbol, side),
            ).fetchone()
            wins = int(row[0] or 0)
            losses = int(row[1] or 0)
    except Exception:
        _swallow()
    n = wins + losses
    # Beta(2,2) prior: stable at small samples and converges toward reality.
    posterior = (wins + 2.0) / (n + 4.0) if n else 0.5
    raw_wr = 100.0 * wins / n if n else 50.0
    return {
        "wins": wins, "losses": losses, "samples": n,
        "raw_win_rate": round(raw_wr, 2),
        "posterior_win_rate": round(100.0 * posterior, 2),
        "reliable": n >= V34_MIN_HISTORY,
    }


def _v34_opportunity(item: dict[str, Any]) -> dict[str, Any]:
    """Score a near-actionable WAIT without pretending it is a profit probability."""
    debate = item.get("deep_consensus_v30") or {}
    long = debate.get("long") or {}
    short = debate.get("short") or {}
    ls = safe_float(long.get("score"), 0.0)
    ss = safe_float(short.get("score"), 0.0)
    margin = ls - ss
    side = "LONG" if margin >= V34_MIN_MARGIN else "SHORT" if margin <= -V34_MIN_MARGIN else "WAIT"
    chosen = long if side == "LONG" else short if side == "SHORT" else {}
    if not chosen:
        return {"version": V34_VERSION, "state": "NO_EDGE", "score": 0.0, "candidate": "WAIT"}

    dq = safe_float(chosen.get("data_quality"), 0.0)
    quality = safe_float(chosen.get("quality"), 0.0)
    rr = safe_float(chosen.get("rr"), 0.0)
    contradiction = safe_float(chosen.get("contradiction"), 1.0)
    support = int(chosen.get("support", 0) or 0)
    oppose = int(chosen.get("oppose", 0) or 0)
    hard = list(chosen.get("hard_blocks") or [])
    history = _v34_history(_normalize_symbol(item.get("symbol") or ""), side)

    # Each component is bounded. This is an evidence score, not win probability.
    margin_score = clamp((abs(margin) - V34_MIN_MARGIN) / 0.14 * 100.0, 0.0, 100.0)
    dq_score = clamp((dq - V34_MIN_DQ) / 35.0 * 100.0, 0.0, 100.0)
    quality_score = clamp((quality - V34_MIN_QUALITY) / 35.0 * 100.0, 0.0, 100.0)
    rr_score = clamp((rr - V34_MIN_RR) / 0.90 * 100.0, 0.0, 100.0)
    support_score = clamp(support * 25.0 - oppose * 15.0, 0.0, 100.0)
    contradiction_score = clamp((V34_MAX_CONTRADICTION - contradiction) / V34_MAX_CONTRADICTION * 100.0, 0.0, 100.0)
    history_score = history["posterior_win_rate"] if history["reliable"] else 50.0

    score = (
        margin_score * 0.25 + quality_score * 0.20 + dq_score * 0.15 +
        support_score * 0.15 + rr_score * 0.10 + contradiction_score * 0.10 +
        history_score * 0.05
    )
    safety_block = (
        bool(hard) or dq < V34_MIN_DQ or quality < V34_MIN_QUALITY or
        rr < V34_MIN_RR or contradiction >= V34_MAX_CONTRADICTION
    )
    promote = side in {"LONG", "SHORT"} and score >= V34_PROMOTE_SCORE and not safety_block
    return {
        "version": V34_VERSION,
        "state": "PROMOTE_EARLY" if promote else "WATCH",
        "candidate": side,
        "score": round(clamp(score, 0.0, 100.0), 1),
        "margin": round(margin, 4),
        "data_quality": round(dq, 1),
        "signal_quality": round(quality, 1),
        "rr": round(rr, 2),
        "support": support,
        "opposition": oppose,
        "contradiction": round(contradiction, 3),
        "history": history,
        "safety_block": safety_block,
        "components": {
            "margin": round(margin_score, 1), "quality": round(quality_score, 1),
            "data": round(dq_score, 1), "support": round(support_score, 1),
            "rr": round(rr_score, 1), "contradiction": round(contradiction_score, 1),
            "history": round(history_score, 1),
        },
        "note": "Evidence score only; not a guaranteed probability of profit.",
    }


def _v34_apply(item: dict[str, Any]) -> dict[str, Any]:
    """Final opportunity layer above the canonical evidence stack."""
    try:
        opp = _v34_opportunity(item)
        item["v34_opportunity"] = opp
        item.setdefault("fusion", {})["v34_opportunity"] = opp
        current = str(item.get("decision_tag") or item.get("decision") or "WAIT").upper()
        # Only promote a WAIT that is already supported by the existing central
        # debate. Never flip a valid LONG/SHORT and never bypass hard safety blocks.
        if current == "WAIT" and opp.get("state") == "PROMOTE_EARLY":
            decision = str(opp.get("candidate") or "WAIT")
            item["decision_tag"] = decision
            item["decision"] = decision
            item["bias"] = "صعودی" if decision == "LONG" else "نزولی"
            item["entry_mode"] = "EARLY"
            item["decision_state"] = "CENTRAL_V34_EARLY"
            item["signal_tag"] = f"CENTRAL V34 OPPORTUNITY — {decision}"
            # Confidence is increased modestly by evidence quality, never to 100.
            old = safe_float(item.get("decision_confidence"), 50.0)
            boost = min(8.0, max(2.0, (safe_float(opp.get("score"), 66.0) - 60.0) * 0.20))
            item["decision_confidence"] = round(clamp(max(old, 50.0) + boost, 0.0, 96.0), 1)
            item["central_reason_fa"] = "فرصت نزدیک به فعال‌شدن با اجماع شواهد، Data quality و RR معتبر؛ V34 آن را از WAIT به EARLY ارتقا داد."
            item["v34_promoted"] = True
        else:
            item["v34_promoted"] = False
        item["decision_architecture"] = {
            "type": "SINGLE_CENTRAL_GOVERNOR_WITH_ADAPTIVE_EVIDENCE",
            "authoritative_source": TITAN_CENTRAL_VERSION,
            "opportunity_layer": V34_VERSION,
            "final_decision": item.get("decision_tag", "WAIT"),
            "legacy_engines_are_evidence_only": True,
        }
        return item
    except Exception as exc:
        LOGGER.debug("V34 adaptive trust failed: %s", exc)
        item["v34_opportunity"] = {"version": V34_VERSION, "state": "DEGRADED", "score": 0.0}
        item["v34_promoted"] = False
        return item

# ============================================================
# TITAN V35 — CANONICAL LIVE-PRICE / LEVEL SYNCHRONIZATION
# ------------------------------------------------------------
# One authoritative spot snapshot is used for the public dashboard price,
# entry, SL/TP, RR, forecast anchor and live-price metadata. Closed-candle
# indicators remain based on closed OHLCV; only price-dependent outputs are
# re-anchored. No signal is fabricated when a fresh live price is unavailable.
# ============================================================
V35_VERSION = "TITAN-V35-CANONICAL-LIVE-SNAPSHOT"
V35_MAX_LIVE_AGE_SEC = 8.0
V35_REBASE_MAX_AGE_SEC = 12.0


def _v35_get_live_snapshot(symbol: str, max_age: float = V35_MAX_LIVE_AGE_SEC) -> dict[str, Any]:
    """Return the freshest available Binance spot snapshot for one symbol."""
    sym = _normalize_symbol(symbol)
    now = time.time()
    with LIVE_LOCK:
        info = dict(LIVE_PRICES.get(sym) or {})
    px = safe_float(info.get("price"), 0.0)
    ts = safe_float(info.get("ts"), 0.0)
    age = now - ts if ts > 0 else float("inf")
    if px > 0 and age <= float(max_age):
        return {"price": px, "ts": ts, "age_sec": max(0.0, age),
                "source": info.get("source") or "Binance"}

    # The background live engine normally keeps this hot. A direct refresh is
    # the fail-safe for a slow/stopped worker, and is limited to this symbol.
    try:
        fresh = _fetch_live_prices([sym])
        px = safe_float(fresh.get(sym), 0.0)
        if px > 0:
            _register_live_price(sym, px, "REST-direct")
            with LIVE_LOCK:
                info = dict(LIVE_PRICES.get(sym) or {})
            ts = safe_float(info.get("ts"), time.time())
            return {"price": px, "ts": ts,
                    "age_sec": max(0.0, time.time() - ts),
                    "source": info.get("source") or "REST-direct"}
    except Exception as exc:
        LOGGER.debug("V35 direct live snapshot failed %s: %s", sym, exc)

    return {"price": px, "ts": ts, "age_sec": age,
            "source": info.get("source") or "cache", "fresh": False}


def _v35_rebase_price_dependent_outputs(item: dict[str, Any], snapshot: dict[str, Any]) -> dict[str, Any]:
    """Make all public price/entry/exit outputs coherent with one live price."""
    if not item or not snapshot:
        return item
    live = safe_float(snapshot.get("price"), 0.0)
    if live <= 0:
        item["live_sync"] = False
        item["live_sync_reason"] = "fresh_live_price_unavailable"
        return item

    now = time.time()
    old = _v29_num_price(item.get("price_raw") or item.get("price"))
    if old <= 0:
        old = live
    ratio = live / old if old > 0 else 1.0

    item.setdefault("signal_snapshot", {})
    if "price" not in item["signal_snapshot"]:
        item["signal_snapshot"]["price"] = old
        item["signal_snapshot"]["timestamp"] = item.get("scan_timestamp", now)

    item["price_raw"] = live
    item["live_price"] = live
    item["entry_raw"] = live
    item["price"] = smart_format(live)
    item["entry_valid"] = smart_format(live)

    # Directional exits are percentage-rebased from the exact signal snapshot.
    # If a final direction was promoted after the original levels were built,
    # rebuild them from the current price and validate orientation/RR first.
    decision = str(item.get("decision_tag") or item.get("decision") or "WAIT").upper()
    if decision in {"LONG", "SHORT"}:
        for key in ("stop_loss", "tp1", "tp2"):
            if key in item:
                item[key] = _v29_shift_price_field(item.get(key), ratio)

        sl = _v29_num_price(item.get("stop_loss"))
        tp1 = _v29_num_price(item.get("tp1"))
        tp2 = _v29_num_price(item.get("tp2"))
        check = _v12_level_integrity(live, sl, tp1, tp2, decision)
        if not check.get("ok"):
            rsl, rtp1, rtp2 = _v12_rebuild_directional_levels(item, decision)
            check2 = _v12_level_integrity(live, rsl, rtp1, rtp2, decision)
            if check2.get("ok"):
                sl, tp1, tp2 = rsl, rtp1, rtp2
                check = check2
                item["level_rebased_by_v35"] = True
            else:
                # Never expose a directional signal with invalid levels.
                item["decision_tag"] = "WAIT"
                item["decision"] = "WAIT"
                item["bias"] = "خنثی"
                item["entry_mode"] = "WAIT"
                item["signal_tag"] = "V35 SAFETY WAIT — LIVE LEVELS INVALID"
                item["level_rebased_by_v35"] = False
                item["live_sync_reason"] = "directional_levels_invalid_after_live_rebase"
                sl = tp1 = tp2 = 0.0
        if sl > 0 and tp1 > 0 and tp2 > 0:
            item["stop_loss_raw"] = float(sl)
            item["tp1_raw"] = float(tp1)
            item["tp2_raw"] = float(tp2)
            item["stop_loss"] = smart_format(sl)
            item["tp1"] = smart_format(tp1)
            item["tp2"] = smart_format(tp2)
            item["rr_tp1"] = check.get("rr1", 0.0)
            item["rr_tp2"] = check.get("rr2", 0.0)
            item["effective_rr_tp1"] = item["rr_tp1"]
            item["effective_rr_tp2"] = item["rr_tp2"]
    else:
        # WAIT has no actionable exit levels. Its entry anchor is always live.
        item["entry_raw"] = live
        item["entry_valid"] = smart_format(live)

    sl = _v29_num_price(item.get("stop_loss"))
    tp1 = _v29_num_price(item.get("tp1"))
    tp2 = _v29_num_price(item.get("tp2"))
    if sl > 0:
        risk = abs(live - sl)
        item["risk_distance_pct"] = round(risk / live * 100.0, 3)
        if risk > 0 and tp1 > 0:
            item["rr_tp1"] = round(abs(tp1 - live) / risk, 3)
            item["effective_rr_tp1"] = item["rr_tp1"]
        if risk > 0 and tp2 > 0:
            item["rr_tp2"] = round(abs(tp2 - live) / risk, 3)
            item["effective_rr_tp2"] = item["rr_tp2"]

    # Keep scenario prices anchored to exactly the same live reference.
    fc = item.get("candle_forecast")
    if isinstance(fc, dict):
        fc["last_price"] = round(live, 8)
        if old > 0 and math.isfinite(ratio) and ratio > 0:
            for candle in fc.get("candles", []) or []:
                if isinstance(candle, dict):
                    for key in ("open", "high", "low", "close", "mid", "band_low", "band_high"):
                        if key in candle:
                            try:
                                candle[key] = round(float(candle[key]) * ratio, 8)
                            except Exception:
                                _swallow()

    age = max(0.0, now - safe_float(snapshot.get("ts"), now))
    item["live_price_source"] = snapshot.get("source") or "Binance"
    item["live_price_ts"] = safe_float(snapshot.get("ts"), now)
    item["live_price_age_sec"] = round(age, 3)
    item["live_sync"] = bool(age <= V35_MAX_LIVE_AGE_SEC)
    item["price_delta_from_scan_pct"] = round((live / old - 1.0) * 100.0, 4) if old > 0 else 0.0
    item["price_sync_version"] = V35_VERSION
    item["price_sync"] = {
        "authoritative_price": live,
        "source": item["live_price_source"],
        "timestamp": item["live_price_ts"],
        "age_sec": item["live_price_age_sec"],
        "entry_anchor": live,
        "levels_rebased": bool(item.get("level_rebased_by_v35", False) or decision in {"LONG", "SHORT"}),
        "single_price_source_for_public_outputs": True,
    }
    return item



# ============================================================
# TITAN V36 — QUANTUM RESONANCE EDGE (magical upgrade layer)
# ------------------------------------------------------------
# Cross-asset resonance, drift-aware confidence decay, and
# multi-horizon agreement score. Analysis-only; never invents
# win probability. Can only demote unsafe signals or modestly
# boost a coherent multi-horizon edge that is already present.
# ============================================================
V36_VERSION = "TITAN-V36-QUANTUM-RESONANCE-EDGE"
V36_DRIFT_KILL_PCT = 1.85
V36_RESONANCE_BOOST_MIN = 0.62
V36_MAX_CONF_BOOST = 6.0
_V36_RESONANCE_CACHE: dict[str, Any] = {"ts": 0.0, "matrix": {}}
_V36_RESONANCE_LOCK = threading.RLock()


def _v36_horizon_agreement(item: dict[str, Any]) -> dict[str, Any]:
    """Score agreement across HTF/MTF/LTF + forecast path + structure."""
    tf = item.get("tf_scores") or item.get("tfs") or {}
    s15 = safe_float(tf.get("15m"), 50.0)
    s1h = safe_float(tf.get("1h"), 50.0)
    s4h = safe_float(tf.get("4h"), 50.0)
    s1d = safe_float(tf.get("1d"), 50.0)
    decision = str(item.get("decision_tag") or item.get("decision") or "WAIT").upper()

    def lean(sc: float) -> float:
        return clamp((sc - 50.0) / 50.0, -1.0, 1.0)

    leans = [lean(s15), lean(s1h), lean(s4h), lean(s1d)]
    fc = item.get("candle_forecast") or {}
    fc_bias = str(fc.get("overall_bias") or "")
    if fc_bias == "صعودی":
        leans.append(0.45)
    elif fc_bias == "نزولی":
        leans.append(-0.45)
    struct = item.get("structure") if isinstance(item.get("structure"), dict) else {}
    sb = str(struct.get("bias") or item.get("structure_bias") or "")
    if sb == "صعودی":
        leans.append(0.40)
    elif sb == "نزولی":
        leans.append(-0.40)

    if not leans:
        return {"agreement": 0.0, "direction": "WAIT", "n": 0}
    mean = sum(leans) / len(leans)
    var = sum((x - mean) ** 2 for x in leans) / max(1, len(leans))
    cohesion = float(clamp(1.0 - (var ** 0.5) * 1.8, 0.0, 1.0))
    magnitude = abs(mean)
    agreement = float(clamp(cohesion * (0.45 + 0.55 * magnitude), 0.0, 1.0))
    direction = "LONG" if mean > 0.08 else "SHORT" if mean < -0.08 else "WAIT"
    aligned = direction == decision if decision in {"LONG", "SHORT"} else False
    return {
        "agreement": round(agreement, 4),
        "mean_lean": round(mean, 4),
        "cohesion": round(cohesion, 4),
        "direction": direction,
        "aligned_with_decision": aligned,
        "n": len(leans),
    }


def _v36_price_drift_gate(item: dict[str, Any]) -> dict[str, Any]:
    """Kill directional signals when live price has run away from the scan snapshot."""
    snap = item.get("signal_snapshot") if isinstance(item.get("signal_snapshot"), dict) else {}
    snap_px = safe_float(snap.get("price"), 0.0)
    live = safe_float(item.get("price_raw") or item.get("live_price"), 0.0)
    decision = str(item.get("decision_tag") or item.get("decision") or "WAIT").upper()
    if snap_px <= 0 or live <= 0 or decision not in {"LONG", "SHORT"}:
        return {"drift_pct": 0.0, "kill": False, "reason": ""}
    drift = (live / snap_px - 1.0) * 100.0
    adverse = (decision == "LONG" and drift > V36_DRIFT_KILL_PCT) or (
        decision == "SHORT" and drift < -V36_DRIFT_KILL_PCT
    )
    extreme = abs(drift) > V36_DRIFT_KILL_PCT * 1.6
    kill = bool(adverse or extreme)
    reason = ""
    if adverse:
        reason = f"adverse_drift_{drift:+.2f}%"
    elif extreme:
        reason = f"extreme_drift_{drift:+.2f}%"
    return {"drift_pct": round(drift, 3), "kill": kill, "reason": reason, "snap": snap_px, "live": live}


def _v36_cross_asset_resonance(symbol: str, decision: str, cache_rows: list) -> dict[str, Any]:
    """Soft portfolio resonance: same-side cluster reduces edge quality."""
    if decision not in {"LONG", "SHORT"} or not cache_rows:
        return {"same_side": 0, "penalty": 0.0, "note": ""}
    majors = {"BTC/USDT", "ETH/USDT", "BNB/USDT", "SOL/USDT", "XRP/USDT"}
    sym = _normalize_symbol(symbol)
    same = 0
    for row in cache_rows:
        other = _normalize_symbol(row.get("symbol") or "")
        if other == sym:
            continue
        od = str(row.get("decision_tag") or row.get("decision") or "").upper()
        if od == decision:
            same += 1
    penalty = 0.0
    note = ""
    if same >= 6:
        penalty = 10.0
        note = f"رزونانس سبد: {same} سیگنال هم‌جهت فعال"
    elif same >= 4:
        penalty = 5.0
        note = f"فشار خوشه‌ای: {same} سیگنال هم‌جهت"
    if sym in majors and same >= 3:
        penalty = max(penalty, 4.0)
    return {"same_side": same, "penalty": penalty, "note": note}


def _v36_apply(item: dict[str, Any], cache_rows: Optional[list] = None) -> dict[str, Any]:
    """Quantum Resonance final polish — demote on drift, modest boost on pure agreement."""
    try:
        decision = str(item.get("decision_tag") or item.get("decision") or "WAIT").upper()
        agree = _v36_horizon_agreement(item)
        drift = _v36_price_drift_gate(item)
        resonance = _v36_cross_asset_resonance(
            str(item.get("symbol") or ""), decision, list(cache_rows or [])
        )
        killed = False
        boosted = False
        notes: list[str] = []

        if decision in {"LONG", "SHORT"} and drift.get("kill"):
            item["decision_tag"] = "WAIT"
            item["decision"] = "WAIT"
            item["bias"] = "خنثی"
            item["entry_mode"] = "WAIT"
            item["signal_tag"] = "V36 RESONANCE WAIT — PRICE DRIFT"
            item["central_reason_fa"] = (
                f"قیمت از اسنپ‌شات سیگنال بیش از حد فاصله گرفته ({drift.get('reason')}); "
                "سیگنال جهت‌دار باطل شد."
            )
            killed = True
            notes.append(str(drift.get("reason") or "drift_kill"))

        if not killed and decision in {"LONG", "SHORT"}:
            if (
                agree.get("direction") in {"LONG", "SHORT"}
                and agree.get("direction") != decision
                and agree.get("agreement", 0) >= 0.55
            ):
                item["decision_tag"] = "WAIT"
                item["decision"] = "WAIT"
                item["bias"] = "خنثی"
                item["entry_mode"] = "WAIT"
                item["signal_tag"] = "V36 RESONANCE WAIT — HORIZON DISCORD"
                item["central_reason_fa"] = "اجماع افق‌های زمانی با جهت سیگنال در تضاد است."
                killed = True
                notes.append("horizon_discord")
            elif agree.get("aligned_with_decision") and agree.get("agreement", 0) >= V36_RESONANCE_BOOST_MIN:
                conf = safe_float(item.get("decision_confidence"), 50.0)
                boost = min(V36_MAX_CONF_BOOST, (agree["agreement"] - V36_RESONANCE_BOOST_MIN) * 18.0)
                boost = max(0.0, boost - safe_float(resonance.get("penalty"), 0.0) * 0.35)
                if boost >= 1.0:
                    item["decision_confidence"] = round(clamp(conf + boost, 0.0, 96.0), 1)
                    boosted = True
                    notes.append(f"resonance_boost_+{boost:.1f}")
            if resonance.get("penalty", 0) >= 8 and not killed:
                conf = safe_float(item.get("decision_confidence"), 50.0)
                item["decision_confidence"] = round(max(35.0, conf - resonance["penalty"]), 1)
                notes.append(resonance.get("note") or "cluster_pressure")

        item["v36_resonance"] = {
            "version": V36_VERSION,
            "horizon_agreement": agree,
            "price_drift": drift,
            "cross_asset": resonance,
            "killed": killed,
            "boosted": boosted,
            "notes": notes,
        }
        item.setdefault("fusion", {})["v36_resonance"] = item["v36_resonance"]
        arch = item.get("decision_architecture") if isinstance(item.get("decision_architecture"), dict) else {}
        arch = dict(arch)
        arch["resonance_layer"] = V36_VERSION
        arch["final_decision"] = item.get("decision_tag", "WAIT")
        item["decision_architecture"] = arch
        return item
    except Exception as exc:
        LOGGER.debug("V36 resonance failed: %s", exc)
        item["v36_resonance"] = {"version": V36_VERSION, "error": str(exc)[:180]}
        return item



# ============================================================
# TITAN V40 — FIVE HARD FIXES IN ONE LAYER
# 1) Precision thresholds already applied globally
# 2) Paper integrity already applied
# 3) DB self-heal on startup (corrupt paper + stuck PENDING)
# 4) Unified maintenance brain (central/v32/forecast/journal/paper)
# 5) Final precision gate (history ban + confluence + integrity)
# ============================================================
V40_VERSION = "TITAN-V41-BALANCED-OPPORTUNITY"
V40_MIN_LIVE_AGE = 12.0
V40_MIN_RR1 = 1.10
V40_MIN_RR2 = 1.40
V40_MIN_CONF = 52.0
V40_MIN_AGREE = 0.38
V40_BAN_WR = 30.0
V40_BAN_N = 8
V40_SOFT_WR = 40.0
V40_GLOBAL_SHORT_WR = 35.0
V40_GLOBAL_SHORT_N = 20
V40_LOOKBACK = 250
_V40_HIST: dict[str, Any] = {"ts": 0.0, "by_key": {}, "g_short": {}, "g_long": {}}
_V40_HIST_LOCK = threading.RLock()


def _v40_db_self_heal() -> dict[str, Any]:
    """One-shot hygiene: close corrupt papers, expire impossible PENDING rows."""
    report = {"paper_invalid": 0, "paper_absurd_r": 0, "forecast_expired": 0,
              "v32_expired": 0, "journal_expired": 0, "central_forced": 0}
    now = time.time()
    try:
        with DB_LOCK, db_conn() as con:
            # Corrupt closed papers with exit=0 or |R|>20
            cur = con.execute(
                "SELECT id, entry, exit_price, r_multiple, tp1, sl FROM paper_trades WHERE status='CLOSED'"
            ).fetchall()
            for row in cur:
                rid = row[0]
                entry = safe_float(row[1], 0)
                exit_px = safe_float(row[2], 0)
                r_mult = safe_float(row[3], 0)
                tp1 = safe_float(row[4], 0)
                sl = safe_float(row[5], 0)
                bad = False
                reason = None
                if tp1 <= 0 or sl <= 0 or entry <= 0:
                    bad, reason = True, "INVALID_LEVELS_HEALED"
                elif exit_px <= 0:
                    bad, reason = True, "INVALID_EXIT_HEALED"
                elif abs(r_mult) > 8:
                    bad, reason = True, "ABSURD_R_HEALED"
                if bad:
                    con.execute(
                        "UPDATE paper_trades SET pnl_pct=0, r_multiple=0, reason=?, exit_price=? WHERE id=?",
                        (reason, entry if exit_px <= 0 else exit_px, rid),
                    )
                    report["paper_absurd_r" if "R" in (reason or "") else "paper_invalid"] += 1
            # Open papers with invalid levels
            for row in con.execute("SELECT id, entry, sl, tp1 FROM paper_trades WHERE status='OPEN'").fetchall():
                if safe_float(row[1], 0) <= 0 or safe_float(row[2], 0) <= 0 or safe_float(row[3], 0) <= 0:
                    con.execute(
                        "UPDATE paper_trades SET status='CLOSED', exit_price=?, pnl_pct=0, r_multiple=0, closed_at=?, reason=? WHERE id=?",
                        (safe_float(row[1], 0), now, "INVALID_LEVELS", row[0]),
                    )
                    report["paper_invalid"] += 1
            # Forecasts stuck PENDING past horizon+1h → MISS
            for row in con.execute(
                "SELECT id, created_at, horizon_minutes FROM forecasts WHERE outcome='PENDING'"
            ).fetchall():
                end = safe_float(row[1], 0) + int(row[2] or 240) * 60 + 3600
                if now >= end:
                    con.execute(
                        "UPDATE forecasts SET outcome='MISS', evaluated_at=?, hit_type='HEALED_EXPIRE' WHERE id=?",
                        (now, row[0]),
                    )
                    report["forecast_expired"] += 1
            # V32 audit stuck past horizon+2h
            try:
                for row in con.execute(
                    "SELECT id, created_at, horizon_minutes FROM v32_forecast_audit WHERE outcome='PENDING'"
                ).fetchall():
                    end = safe_float(row[1], 0) + int(row[2] or 240) * 60 + 7200
                    if now >= end:
                        con.execute(
                            "UPDATE v32_forecast_audit SET outcome='EXPIRED', evaluated_at=?, return_pct=0 WHERE id=?",
                            (now, row[0]),
                        )
                        report["v32_expired"] += 1
            except Exception:
                _swallow()
            # V22 journal PENDING older than 6h → EXPIRED
            try:
                for row in con.execute(
                    "SELECT id, created_at FROM decision_journal_v22 WHERE outcome='PENDING'"
                ).fetchall():
                    if now - safe_float(row[1], 0) > 6 * 3600:
                        con.execute(
                            "UPDATE decision_journal_v22 SET outcome='EXPIRED' WHERE id=?",
                            (row[0],),
                        )
                        report["journal_expired"] += 1
            except Exception:
                _swallow()
            con.commit()
    except Exception as exc:
        LOGGER.warning("V40 DB self-heal failed: %s", exc)
        report["error"] = str(exc)[:200]
    LOGGER.info("V40 DB self-heal: %s", report)
    return report


def _v40_unified_maintenance() -> dict[str, Any]:
    """Always-on evaluation brain so PENDING does not rot and learning continues."""
    out: dict[str, Any] = {}
    try:
        out["central"] = _central_evaluate_pending() if "_central_evaluate_pending" in globals() else {}
    except Exception as exc:
        out["central_err"] = str(exc)[:120]
    try:
        if "v32_evaluate_pending" in globals():
            out["v32"] = v32_evaluate_pending()
    except Exception as exc:
        out["v32_err"] = str(exc)[:120]
    try:
        evaluate_pending_forecasts()
        out["forecasts"] = "ok"
    except Exception as e:
        out["forecasts_err"] = str(e)[:120]
    try:
        evaluate_paper_trades()
        out["paper"] = "ok"
    except Exception as e:
        out["paper_err"] = str(e)[:120]
    try:
        _central_load_weights()
        out["weights_reloaded"] = True
    except Exception:
        _swallow()
    try:
        with _V40_HIST_LOCK:
            _V40_HIST["ts"] = 0.0  # force hist refresh next gate
    except Exception:
        _swallow()
    return out


def _v40_maintenance_loop() -> None:
    """Dedicated self-healing loop — independent of scan success."""
    # Initial heal once storage is ready
    try:
        _v40_db_self_heal()
    except Exception as exc:
        LOGGER.debug("initial heal: %s", exc)
    _tick = 0
    while not LIVE_STOP.is_set():
        try:
            _v40_unified_maintenance()
        except Exception as exc:
            LOGGER.debug("V40 maintenance: %s", exc)
        _tick += 1
        if _tick % 50 == 0:   # ~ every 29 minutes
            try:
                with DB_LOCK, db_conn() as _c:
                    _c.execute("PRAGMA wal_checkpoint(PASSIVE)")
                    _c.execute("PRAGMA optimize")
            except Exception as exc:
                LOGGER.debug("DB periodic maintenance: %s", exc)
        LIVE_STOP.wait(35)


def _v40_refresh_hist(force: bool = False) -> dict[str, Any]:
    now = time.time()
    with _V40_HIST_LOCK:
        if not force and _V40_HIST["ts"] and now - _V40_HIST["ts"] < 45:
            return _V40_HIST
    by_key: dict[str, dict[str, float]] = {}
    g_short = {"wins": 0.0, "losses": 0.0}
    g_long = {"wins": 0.0, "losses": 0.0}
    try:
        with DB_LOCK, db_conn() as con:
            rows = con.execute(
                """SELECT symbol, decision, outcome FROM central_predictions
                   WHERE outcome IN ('WIN','LOSS') AND decision IN ('LONG','SHORT')
                   ORDER BY id DESC LIMIT ?""",
                (V40_LOOKBACK,),
            ).fetchall()
        for r in rows:
            sym = _normalize_symbol(r[0] if not isinstance(r, sqlite3.Row) else r["symbol"])
            side = str((r[1] if not isinstance(r, sqlite3.Row) else r["decision"]) or "").upper()
            outc = str((r[2] if not isinstance(r, sqlite3.Row) else r["outcome"]) or "").upper()
            key = f"{sym}|{side}"
            st = by_key.setdefault(key, {"wins": 0.0, "losses": 0.0})
            if outc == "WIN":
                st["wins"] += 1
                (g_short if side == "SHORT" else g_long)["wins"] += 1
            else:
                st["losses"] += 1
                (g_short if side == "SHORT" else g_long)["losses"] += 1
        for st in by_key.values():
            n = st["wins"] + st["losses"]
            st["samples"] = n
            st["wr"] = 100.0 * st["wins"] / n if n else 50.0
        for g in (g_short, g_long):
            n = g["wins"] + g["losses"]
            g["samples"] = n
            g["wr"] = 100.0 * g["wins"] / n if n else 50.0
    except Exception as exc:
        LOGGER.debug("V40 hist: %s", exc)
    with _V40_HIST_LOCK:
        _V40_HIST.update({"ts": now, "by_key": by_key, "g_short": g_short, "g_long": g_long})
        return _V40_HIST


def _v40_horizon_agree(item: dict[str, Any]) -> dict[str, Any]:
    tf = item.get("tf_scores") or item.get("tfs") or {}
    scores = [safe_float(tf.get(k), 50.0) for k in ("15m", "1h", "4h", "1d")]
    leans = [(s - 50.0) / 50.0 for s in scores]
    fc = str((item.get("candle_forecast") or {}).get("overall_bias") or "")
    if fc == "صعودی":
        leans.append(0.4)
    elif fc == "نزولی":
        leans.append(-0.4)
    struct = item.get("structure") if isinstance(item.get("structure"), dict) else {}
    sb = str(struct.get("bias") or item.get("structure_bias") or "")
    if sb == "صعودی":
        leans.append(0.35)
    elif sb == "نزولی":
        leans.append(-0.35)
    # BTC regime soft lean for alts
    btc = str(item.get("btc_trend") or "")
    sym = str(item.get("symbol") or "")
    if "BTC" not in sym.upper():
        if btc == "صعودی":
            leans.append(0.2)
        elif btc == "نزولی":
            leans.append(-0.2)
    if not leans:
        return {"agreement": 0.0, "direction": "WAIT", "mean": 0.0}
    mean = sum(leans) / len(leans)
    var = sum((x - mean) ** 2 for x in leans) / max(1, len(leans))
    cohesion = float(clamp(1.0 - (var ** 0.5) * 1.7, 0.0, 1.0))
    agreement = float(clamp(cohesion * (0.4 + 0.6 * abs(mean)), 0.0, 1.0))
    direction = "LONG" if mean > 0.10 else "SHORT" if mean < -0.10 else "WAIT"
    return {"agreement": round(agreement, 4), "direction": direction, "mean": round(mean, 4)}


def _v40_force_wait(item: dict[str, Any], reason_fa: str, code: str) -> dict[str, Any]:
    x = dict(item or {})
    x["decision_tag"] = x["decision"] = "WAIT"
    x["bias"] = "خنثی"
    x["entry_mode"] = "WAIT"
    x["signal_tag"] = f"V40 PRECISION WAIT — {code}"
    x["central_reason_fa"] = reason_fa
    x["v40_demoted"] = True
    x["v40_demote_code"] = code
    for k in ("stop_loss", "tp1", "tp2"):
        x[k] = "—"
    for k in ("stop_loss_raw", "tp1_raw", "tp2_raw", "effective_rr_tp1", "effective_rr_tp2"):
        x[k] = 0.0
    x["rr_tp1"] = x["rr_tp2"] = "—"
    return x


def _v40_precision_gate(item: dict[str, Any], cache_rows: Optional[list] = None) -> dict[str, Any]:
    """Final public authority — history + integrity + multi-horizon confluence."""
    x = dict(item or {})
    decision = str(x.get("decision_tag") or x.get("decision") or "WAIT").upper()
    notes: list[str] = []
    hist = _v40_refresh_hist()
    sym = _normalize_symbol(x.get("symbol") or "")
    key = f"{sym}|{decision}"
    st = (hist.get("by_key") or {}).get(key) or {"wins": 0, "losses": 0, "samples": 0, "wr": 50.0}
    g_short = hist.get("g_short") or {"wr": 50.0, "samples": 0}
    g_long = hist.get("g_long") or {"wr": 50.0, "samples": 0}

    if decision in {"LONG", "SHORT"}:
        if st.get("samples", 0) >= V40_BAN_N and st.get("wr", 50) < V40_BAN_WR:
            return _v40_force_wait(
                x, f"سابقه {sym} {decision}: WR {st['wr']:.0f}% از {int(st['samples'])} — مسدود.", "HISTORY_BAN")
        if decision == "SHORT" and g_short.get("samples", 0) >= V40_GLOBAL_SHORT_N and g_short.get("wr", 50) < V40_GLOBAL_SHORT_WR:
            return _v40_force_wait(
                x, f"رژیم SHORT ضعیف (WR {g_short['wr']:.0f}%) — SHORT جدید نیست.", "SHORT_REGIME_BLOCK")
        # Soft BTC regime: haircut weak alt-SHORT in BTC uptrend; allow strong ones
        if decision == "SHORT" and "BTC" not in sym.upper() and str(x.get("btc_trend") or "") == "صعودی":
            conf0 = safe_float(x.get("decision_confidence"), 50.0)
            if conf0 < 62:
                return _v40_force_wait(x, "شورت ضعیف آلت در روند صعودی BTC", "BTC_REGIME_SOFT")
            x["decision_confidence"] = round(max(52.0, conf0 - 8.0), 1)
            notes.append("btc_up_short_haircut")

    price = safe_float(x.get("price_raw") or x.get("live_price") or x.get("entry_raw"), 0.0)
    live_sync = bool(x.get("live_sync", False))
    live_age = safe_float(x.get("live_price_age_sec"), 999.0)
    if decision in {"LONG", "SHORT"}:
        if price <= 0:
            return _v40_force_wait(x, "قیمت نامعتبر", "NO_PRICE")
        if live_age > 30:
            return _v40_force_wait(x, f"قیمت زنده خیلی کهنه ({live_age:.0f}s)", "STALE_LIVE")
        if not live_sync or live_age > V40_MIN_LIVE_AGE:
            conf_now = safe_float(x.get("decision_confidence"), 50.0)
            x["decision_confidence"] = round(max(50.0, conf_now - 4.0), 1)
            notes.append(f"live_soft_age_{live_age:.0f}s")

    if decision in {"LONG", "SHORT"} and price > 0:
        sl = safe_float(x.get("stop_loss_raw"), safe_float(str(x.get("stop_loss") or "0").replace(",", ""), 0.0))
        tp1 = safe_float(x.get("tp1_raw"), safe_float(str(x.get("tp1") or "0").replace(",", ""), 0.0))
        tp2 = safe_float(x.get("tp2_raw"), safe_float(str(x.get("tp2") or "0").replace(",", ""), 0.0))
        try:
            chk = _v12_level_integrity(price, sl, tp1, tp2, decision)
            need_rebuild = (not chk.get("ok")) or safe_float(chk.get("rr1"), 0) < V40_MIN_RR1 or safe_float(chk.get("rr2"), 0) < V40_MIN_RR2
            if need_rebuild:
                rsl, rtp1, rtp2 = _v12_rebuild_directional_levels(x, decision)
                chk2 = _v12_level_integrity(price, rsl, rtp1, rtp2, decision)
                if chk2.get("ok") and safe_float(chk2.get("rr1"), 0) >= V40_MIN_RR1 and safe_float(chk2.get("rr2"), 0) >= V40_MIN_RR2:
                    x["stop_loss_raw"], x["tp1_raw"], x["tp2_raw"] = float(rsl), float(rtp1), float(rtp2)
                    x["stop_loss"], x["tp1"], x["tp2"] = smart_format(rsl), smart_format(rtp1), smart_format(rtp2)
                    x["rr_tp1"], x["rr_tp2"] = chk2.get("rr1"), chk2.get("rr2")
                    x["effective_rr_tp1"], x["effective_rr_tp2"] = x["rr_tp1"], x["rr_tp2"]
                    notes.append("levels_rebuilt")
                else:
                    return _v40_force_wait(x, "سطوح یا R:R زیر از استاندارد V40", "BAD_LEVELS")
            else:
                x["rr_tp1"], x["rr_tp2"] = chk.get("rr1"), chk.get("rr2")
                x["effective_rr_tp1"], x["effective_rr_tp2"] = x["rr_tp1"], x["rr_tp2"]
        except Exception:
            return _v40_force_wait(x, "خطا در اعتبارسنجی سطوح", "LEVEL_ERROR")

    agree = _v40_horizon_agree(x)
    if decision in {"LONG", "SHORT"}:
        a_score = safe_float(agree.get("agreement"), 0)
        a_dir = agree.get("direction")
        # Hard kill only when horizons clearly oppose the decision with decent cohesion
        if a_dir in {"LONG", "SHORT"} and a_dir != decision and a_score >= 0.45:
            return _v40_force_wait(
                x, f"اجماع افق‌ها مخالف جهت ({a_dir}, a={a_score:.2f})", "HORIZON_CONFLICT")
        # Soft path: weak agreement reduces confidence instead of killing the opportunity
        if a_dir != decision or a_score < V40_MIN_AGREE:
            conf_now = safe_float(x.get("decision_confidence"), 50.0)
            haircut = 6.0 if a_score < 0.25 else 3.0
            x["decision_confidence"] = round(max(50.0, conf_now - haircut), 1)
            notes.append(f"horizon_soft_{a_dir}_{a_score:.2f}")
        else:
            notes.append(f"horizon_ok_{a_score:.2f}")

    conf = safe_float(x.get("decision_confidence"), 50.0)
    if decision in {"LONG", "SHORT"} and conf < 48.0:
        return _v40_force_wait(x, f"اطمینان خیلی پایین ({conf:.0f})", "LOW_CONF")
    if decision in {"LONG", "SHORT"} and conf < V40_MIN_CONF:
        notes.append(f"conf_borderline_{conf:.0f}")

    atr = safe_float(x.get("atr"), 0.0)
    vwap = safe_float(x.get("vwap"), price)
    stretch = abs(price - vwap) / atr if atr > 0 and price > 0 else 0.0
    if decision in {"LONG", "SHORT"} and stretch > MAX_STRETCH_ATR:
        return _v40_force_wait(x, f"ورود دیر ATR-stretch={stretch:.2f}", "OVEREXTENDED")

    try:
        port = portfolio_side_pressure(decision, sym)
        if decision in {"LONG", "SHORT"} and not port.get("ok", True):
            return _v40_force_wait(x, str(port.get("reason") or "اشباع سبد"), "PORTFOLIO")
    except Exception:
        _swallow()

    if decision in {"LONG", "SHORT"} and st.get("samples", 0) >= V40_BAN_N and st.get("wr", 50) < V40_SOFT_WR:
        conf = max(V40_MIN_CONF, conf - min(15.0, (V40_SOFT_WR - st["wr"]) * 0.4))
        notes.append("hist_haircut")
    if decision in {"LONG", "SHORT"} and st.get("samples", 0) >= 4:
        cap = min(82.0, max(58.0, st["wr"] + 12.0))
        conf = min(conf, cap)
    if decision == "SHORT" and g_short.get("samples", 0) >= 10:
        conf = min(conf, max(58.0, g_short["wr"] + 10.0))
    if decision == "LONG" and g_long.get("samples", 0) >= 10:
        conf = min(conf, max(58.0, g_long["wr"] + 12.0))

    x["decision_confidence"] = round(float(clamp(conf, 0, 82)), 1)
    x["success_prob"] = x["decision_confidence"]
    cal = x.get("probability_calibration") if isinstance(x.get("probability_calibration"), dict) else {}
    is_cal = bool(cal.get("is_calibrated") or safe_float(cal.get("samples"), 0) >= 8)
    cal_val = safe_float(cal.get("calibrated"), conf)
    x["success_probability"] = round(float(clamp(cal_val if is_cal else conf, 5, 80)), 1)
    x["success_probability_is_calibrated"] = is_cal
    x["probability_disclaimer"] = (
        "احتمال کالیبره‌شده از نتایج واقعی" if is_cal else "اطمینان مدل است، نه احتمال تضمینی سود"
    )
    x["reliability_note"] = "فقط سیگنال عبورکرده از V40 Self-Healing Precision منتشر می‌شود."

    if decision == "WAIT":
        x["decision"] = x["decision_tag"] = "WAIT"
        x["bias"] = "خنثی"
    else:
        x["decision"] = x["decision_tag"] = decision
        x["bias"] = "صعودی" if decision == "LONG" else "نزولی"
        try:
            register_portfolio_signal(sym, decision)
        except Exception:
            _swallow()

    x["v40_precision"] = {
        "version": V40_VERSION,
        "passed": decision in {"LONG", "SHORT"},
        "decision": decision,
        "history": st,
        "global_short_wr": g_short.get("wr"),
        "global_long_wr": g_long.get("wr"),
        "horizon": agree,
        "stretch_atr": round(stretch, 2),
        "notes": notes,
        "live_age_sec": round(live_age, 2) if live_age < 1e5 else None,
    }
    x.setdefault("fusion", {})["v40_precision"] = x["v40_precision"]
    arch = dict(x.get("decision_architecture") or {}) if isinstance(x.get("decision_architecture"), dict) else {}
    arch["precision_layer"] = V40_VERSION
    arch["final_decision"] = decision
    arch["self_healing"] = True
    x["decision_architecture"] = arch
    x["authority"] = f"{TITAN_CENTRAL_VERSION}+{V40_VERSION}"
    return x



# ============================================================
# TITAN V42 — INTEGRITY / RISK / PROVENANCE SEAL
# ============================================================
# This is intentionally a *last-mile* layer.  It does not create signals.
# It validates that every published directional signal is internally coherent,
# fresh, risk-defined, auditable, and clearly separated from calibrated odds.
V42_VERSION = "TITAN-V42-INTEGRITY-SEAL"
V42_MAX_LIVE_AGE = 12.0
V42_MIN_RR1 = 1.10
V42_MIN_RR2 = 1.40
V42_MIN_DATA = 45.0
V42_MIN_CAL_SAMPLES = 30
V42_MAX_ATR_STRETCH = 3.25


def _v42_price(x: dict[str, Any]) -> float:
    return safe_float(x.get("price_raw"), safe_float(x.get("live_price"), safe_float(str(x.get("price") or "0").replace(",", ""), 0.0)))


def _v42_levels_ok(price: float, sl: float, tp1: float, tp2: float, side: str) -> bool:
    if min(price, sl, tp1, tp2) <= 0:
        return False
    if side == "LONG":
        return sl < price < tp1 < tp2
    if side == "SHORT":
        return tp2 < tp1 < price < sl
    return True


def _v42_integrity_seal(item: dict[str, Any]) -> dict[str, Any]:
    """Final fail-closed contract for the public signal object.

    The seal is deliberately independent of the score-producing engines.  It
    catches stale data, malformed levels, weak RR, contradictory direction,
    uncalibrated probability claims, and missing audit/provenance fields.
    """
    x = dict(item or {})
    side = str(x.get("decision_tag") or x.get("decision") or "WAIT").upper()
    price = _v42_price(x)
    sl = safe_float(x.get("stop_loss_raw"), safe_float(x.get("stop_loss"), 0.0))
    tp1 = safe_float(x.get("tp1_raw"), safe_float(x.get("tp1"), 0.0))
    tp2 = safe_float(x.get("tp2_raw"), safe_float(x.get("tp2"), 0.0))
    atr = safe_float(x.get("atr"), 0.0)
    live_age = safe_float(x.get("live_price_age_sec"), 1e9)
    dq = x.get("data_quality") if isinstance(x.get("data_quality"), dict) else {}
    data_score = safe_float(dq.get("score"), safe_float(x.get("data_trust"), 0.0))
    reasons: list[str] = []

    if side in {"LONG", "SHORT"}:
        if price <= 0:
            reasons.append("invalid_price")
        if live_age > V42_MAX_LIVE_AGE:
            reasons.append("stale_live_price")
        if data_score and data_score < V42_MIN_DATA:
            reasons.append("low_data_quality")
        if not _v42_levels_ok(price, sl, tp1, tp2, side):
            reasons.append("invalid_directional_levels")
        risk = abs(price - sl)
        rr1 = abs(tp1 - price) / risk if risk > 0 else 0.0
        rr2 = abs(tp2 - price) / risk if risk > 0 else 0.0
        if rr1 < V42_MIN_RR1:
            reasons.append("rr1_below_floor")
        if rr2 < V42_MIN_RR2:
            reasons.append("rr2_below_floor")
        if atr > 0 and risk > 0 and risk / atr > V42_MAX_ATR_STRETCH:
            reasons.append("stop_distance_extreme")
    else:
        rr1 = rr2 = 0.0

    # Probability must never be presented as calibrated unless it is backed by
    # realized samples.  This field is a contract guard, not a prediction.
    cal = x.get("probability_calibration") if isinstance(x.get("probability_calibration"), dict) else {}
    cal_n = int(safe_float(cal.get("samples"), 0))
    is_cal = bool(x.get("success_probability_is_calibrated") and cal.get("is_calibrated"))
    if side in {"LONG", "SHORT"} and is_cal and cal_n < V42_MIN_CAL_SAMPLES:
        is_cal = False
        reasons.append("calibration_sample_floor")

    # A signal can only be published directionally if its final risk contract
    # is coherent.  WAIT is the safe state and remains fully auditable.
    if side in {"LONG", "SHORT"} and reasons:
        x["decision_tag"] = "WAIT"
        x["decision"] = "WAIT"
        x["bias"] = "خنثی"
        x["entry_mode"] = "WAIT"
        x["signal_tag"] = "V42 INTEGRITY BLOCK"
        x["v42_blocked_candidate"] = side
        side = "WAIT"

    x["success_probability_is_calibrated"] = is_cal
    if not is_cal:
        # Keep the raw confidence for backward compatibility but prevent the
        # dashboard/API from implying that it is a measured win probability.
        x["calibrated_probability"] = None
        x["probability_semantics"] = "model_confidence_not_win_probability"
    else:
        x["probability_semantics"] = "realized_calibrated_probability"

    x["v42_integrity"] = {
        "version": V42_VERSION,
        "passed": not bool(reasons),
        "final_decision": side,
        "candidate_before_seal": x.get("v42_blocked_candidate") or side,
        "reasons": reasons,
        "live_age_sec": round(live_age, 3) if live_age < 1e8 else None,
        "data_quality": round(data_score, 2),
        "rr1": round(rr1, 3),
        "rr2": round(rr2, 3),
        "calibration_samples": cal_n,
        "calibrated": is_cal,
        "timestamp": time.time(),
    }
    arch = dict(x.get("decision_architecture") or {}) if isinstance(x.get("decision_architecture"), dict) else {}
    arch.update({
        "integrity_seal": V42_VERSION,
        "final_decision": side,
        "fail_closed": True,
        "probability_is_calibrated": is_cal,
    })
    x["decision_architecture"] = arch
    x["authority"] = f"{x.get('authority') or TITAN_CENTRAL_VERSION}+{V42_VERSION}"
    return x


def titan_system_audit() -> dict[str, Any]:
    """Offline/runtime audit of the major subsystems and persistence contract."""
    checks: dict[str, Any] = {}
    checks["python_imports"] = True
    checks["central_governor"] = callable(globals().get("_central_decide"))
    checks["real_edge"] = callable(globals().get("_real_edge_engine"))
    checks["v40_precision"] = callable(globals().get("_v40_precision_gate"))
    checks["v42_integrity"] = callable(globals().get("_v42_integrity_seal"))
    checks["v43_unified_governor"] = callable(globals().get("_v43_unified_decide"))
    checks["forecast_evaluator"] = callable(globals().get("_central_evaluate_pending"))
    checks["paper_evaluator"] = callable(globals().get("evaluate_paper_trades"))
    checks["walk_forward"] = callable(globals().get("walk_forward_backtest"))
    checks["neural_engine"] = "TitanNeuralSynapseV9" in globals()
    checks["ai_ensemble"] = callable(globals().get("generate_ai_opinions"))
    checks["live_engine"] = callable(globals().get("start_live_engine"))
    checks["db_path_locked"] = str(DB_PATH).startswith(str(APP_HOME))
    try:
        with DB_LOCK, db_conn() as con:
            tables = {r[0] for r in con.execute("SELECT name FROM sqlite_master WHERE type='table'").fetchall()}
        required = {"central_predictions", "central_component_stats", "central_arbiter_log"}
        checks["required_tables"] = required.issubset(tables)
        checks["table_count"] = len(tables)
    except Exception as exc:
        checks["required_tables"] = False
        checks["db_error"] = str(exc)[:180]
    checks["passed"] = all(v is True for k, v in checks.items() if k not in {"table_count", "db_error"})
    checks["version"] = V42_VERSION
    checks["timestamp"] = _now_iso()
    return checks


# ============================================================
# TITAN V43 — UNIFIED EVIDENCE COORDINATOR / ONE-BRAIN DECISION
# ============================================================
# This layer is the final decision coordinator.  It runs AFTER the evidence
# enrichment layers (V31/V34/V35/V36/V40), so those modules are not merely
# post-decision safety filters: their outputs become evidence for the same
# central arbiter.  No legacy/candidate decision is treated as a vote.
V43_VERSION = "TITAN-V43-UNIFIED-EVIDENCE-COORDINATOR"
V43_MIN_COMPONENTS = 8
V43_MIN_ACTIVE_GROUPS = 4


def _v43_side_from_score(score: float, deadband: float = 0.08) -> tuple[float, float, str]:
    lean = clamp((safe_float(score, 50.0) - 50.0) / 50.0, -1.0, 1.0)
    conf = clamp(abs(lean), 0.0, 1.0)
    side = "LONG" if lean > deadband else "SHORT" if lean < -deadband else "WAIT"
    return lean, conf, side


def _v43_add_vote(votes: dict, name: str, score: float, label: str, group: str,
                  available: bool = True, confidence: float | None = None) -> None:
    if not available:
        return
    lean, conf, side = _v43_side_from_score(score)
    if confidence is not None:
        conf = clamp(safe_float(confidence, conf), 0.0, 1.0)
    votes[name] = {
        "lean": lean, "confidence": conf, "side": side,
        "raw": round(safe_float(score, 50.0), 4), "label": label,
        "group": group, "v43": True,
    }


def _v43_unified_evidence_base(item: dict[str, Any]) -> tuple[dict[str, dict[str, Any]], dict[str, Any]]:
    """Build one auditable evidence map from all available downstream modules.

    The function intentionally converts *module outputs* into evidence rather
    than copying their prior decisions.  This prevents circular reinforcement
    while still making the complete analytical stack visible to the governor.
    """
    votes = _central_votes(item)
    registry: list[dict[str, Any]] = []

    def reg(name: str, group: str, used: bool, note: str = ""):
        registry.append({"module": name, "group": group, "used": bool(used), "note": note})

    # Neural intelligence -------------------------------------------------
    neural = item.get("neural_v9") or (item.get("fusion") or {}).get("neural_v9") or {}
    if isinstance(neural, dict) and neural:
        nscore = safe_float(neural.get("neural_score"), 50.0)
        nconf = clamp(safe_float(neural.get("confidence"), 0.0) / 100.0, 0.0, 1.0)
        _v43_add_vote(votes, "neural_v9", nscore, "سیناپس عصبی V9", "AI_NEURAL", True, max(nconf, 0.05))
        reg("TitanNeuralSynapseV9", "AI_NEURAL", True)
    else:
        reg("TitanNeuralSynapseV9", "AI_NEURAL", False, "no runtime output")

    # Market regime / structure / liquidity / precision ------------------
    regime = item.get("regime") if isinstance(item.get("regime"), dict) else {}
    rname = str(regime.get("regime") or item.get("market_regime") or "").lower()
    rconf = clamp(safe_float(regime.get("confidence"), 0.0) / 100.0, 0.0, 1.0)
    if rname:
        rscore = 65.0 if "up" in rname or rname == "breakout_watch" else 35.0 if "down" in rname else 50.0
        _v43_add_vote(votes, "regime_engine", rscore, "رژیم بازار", "MARKET_CONTEXT", True, max(rconf, 0.20))
        reg("regime", "MARKET_CONTEXT", True, rname)
    else:
        reg("regime", "MARKET_CONTEXT", False)

    structure = item.get("structure") if isinstance(item.get("structure"), dict) else {}
    se = str(structure.get("event") or "").upper()
    sb = str(structure.get("bias") or "").upper()
    if se or sb:
        if se in {"BOS_UP", "BULL_STRUCTURE"} or sb in {"LONG", "صعودی"}: sscore = 68.0
        elif se in {"BOS_DOWN", "BEAR_STRUCTURE"} or sb in {"SHORT", "نزولی"}: sscore = 32.0
        else: sscore = 50.0
        sc = clamp(safe_float(structure.get("confirmation_score"), 50.0) / 100.0, 0.0, 1.0)
        _v43_add_vote(votes, "structure_engine", sscore, "موتور ساختار", "MARKET_CONTEXT", True, max(sc, 0.15))
        reg("structure", "MARKET_CONTEXT", True, se or sb)
    else:
        reg("structure", "MARKET_CONTEXT", False)

    liquidity = item.get("liquidity") if isinstance(item.get("liquidity"), dict) else {}
    if liquidity:
        pressure = clamp(safe_float(liquidity.get("pressure"), 0.0), -1.0, 1.0)
        _v43_add_vote(votes, "liquidity_engine", 50.0 + pressure * 35.0, "نقدشوندگی/فشار", "FLOW", True, clamp(abs(pressure) + 0.15, 0, 1))
        reg("liquidity", "FLOW", True)
    else:
        reg("liquidity", "FLOW", False)

    precision = item.get("precision") if isinstance(item.get("precision"), dict) else {}
    if precision:
        ps = safe_float(precision.get("score"), 50.0)
        _v43_add_vote(votes, "precision_engine", ps, "دقت ورود", "ENTRY_RISK", True, 0.75)
        reg("precision", "ENTRY_RISK", True)
    else:
        reg("precision", "ENTRY_RISK", False)

    # V31 complete suite: use the suite-level independent evidence score and
    # explicitly expose all its internal modules as participating metadata.
    v31 = item.get("v31_edge_suite") if isinstance(item.get("v31_edge_suite"), dict) else {}
    if v31:
        ev = v31.get("evidence_fusion") or {}
        adv = v31.get("adversarial") or {}
        ent = v31.get("entry_stability") or {}
        unc = v31.get("uncertainty") or {}
        robust = safe_float(adv.get("robustness"), 50.0)
        entry = safe_float(ent.get("score"), 50.0)
        indep = clamp(safe_float(ev.get("independence_score"), 0.5), 0.0, 1.0)
        uncertainty = clamp(safe_float(unc.get("uncertainty"), 50.0), 0.0, 100.0)
        v31_score = clamp(0.40 * robust + 0.35 * entry + 25.0 * indep + 0.15 * (100.0 - uncertainty), 0, 100)
        _v43_add_vote(votes, "v31_edge_suite", v31_score, "مجموعه 21 ماژول V31", "ROBUSTNESS_LEARNING", True, 0.75)
        for k, val in v31.items():
            reg("V31." + k, "ROBUSTNESS_LEARNING", isinstance(val, dict) or isinstance(val, (bool, int, float)))
    else:
        reg("V31.edge_suite", "ROBUSTNESS_LEARNING", False)

    # V34 adaptive trust / opportunity -----------------------------------
    v34 = item.get("v34_opportunity") if isinstance(item.get("v34_opportunity"), dict) else {}
    if v34:
        opp = safe_float(v34.get("score"), safe_float(v34.get("opportunity_score"), 50.0))
        _v43_add_vote(votes, "v34_opportunity", opp, "اعتماد تطبیقی/فرصت", "ROBUSTNESS_LEARNING", True, 0.70)
        reg("V34.adaptive_trust", "ROBUSTNESS_LEARNING", True)
    else:
        reg("V34.adaptive_trust", "ROBUSTNESS_LEARNING", False)

    # V36 horizon agreement + cross-asset resonance ---------------------
    v36 = item.get("v36_resonance") if isinstance(item.get("v36_resonance"), dict) else {}
    fusion = item.get("fusion") if isinstance(item.get("fusion"), dict) else {}
    horizon = v36.get("horizon_agreement") if isinstance(v36.get("horizon_agreement"), dict) else {}
    if not horizon:
        horizon = item.get("horizon_agreement") if isinstance(item.get("horizon_agreement"), dict) else {}
    if horizon:
        ag = clamp(safe_float(horizon.get("agreement"), 0.5), 0.0, 1.0)
        direction = str(horizon.get("direction") or "WAIT").upper()
        hscore = 50.0 + (ag * 40.0 if direction == "LONG" else -ag * 40.0 if direction == "SHORT" else 0.0)
        _v43_add_vote(votes, "v36_horizon", hscore, "توافق افق‌های زمانی V36", "MTF_CROSS_ASSET", True, max(ag, 0.15))
        reg("V36.horizon_agreement", "MTF_CROSS_ASSET", True)
    else:
        reg("V36.horizon_agreement", "MTF_CROSS_ASSET", False)
    if v36:
        penalty = safe_float(v36.get("penalty"), 0.0)
        resonance = clamp(50.0 - penalty * 2.0, 0.0, 100.0)
        _v43_add_vote(votes, "v36_resonance", resonance, "رزونانس بین‌دارایی V36", "MTF_CROSS_ASSET", True, 0.65)
        reg("V36.cross_asset_resonance", "MTF_CROSS_ASSET", True)
    else:
        reg("V36.cross_asset_resonance", "MTF_CROSS_ASSET", False)

    # V40 precision is a gate AND an evidence source.  Hard blocks remain
    # authoritative vetoes below, while its score participates in consensus.
    v40 = item.get("v40_precision") if isinstance(item.get("v40_precision"), dict) else {}
    if v40:
        v40_score = safe_float(v40.get("score"), 50.0)
        _v43_add_vote(votes, "v40_precision", v40_score, "گیت دقت V40", "ENTRY_RISK", True, 0.80)
        reg("V40.precision_gate", "ENTRY_RISK", True)
    else:
        reg("V40.precision_gate", "ENTRY_RISK", False)

    # Macro / BTC context -------------------------------------------------
    btc = str(item.get("btc_trend") or "").strip()
    if btc:
        bscore = 65.0 if btc in {"صعودی", "LONG", "UP"} else 35.0 if btc in {"نزولی", "SHORT", "DOWN"} else 50.0
        _v43_add_vote(votes, "btc_macro_context", bscore, "رژیم BTC/ماکرو", "MARKET_CONTEXT", True, 0.55)
        reg("BTC/macro", "MARKET_CONTEXT", True, btc)
    else:
        reg("BTC/macro", "MARKET_CONTEXT", False)

    # Forecast, calibration, learning, research and performance ------------
    fc = item.get("candle_forecast") or item.get("forecast") or {}
    if isinstance(fc, dict) and fc:
        bias = str(fc.get("overall_bias") or "")
        move = safe_float(fc.get("expected_move_pct"), 0.0)
        fscore = 50.0 + clamp(move * 4.0, -20.0, 20.0)
        if bias == "صعودی": fscore = max(fscore, 53.0)
        elif bias == "نزولی": fscore = min(fscore, 47.0)
        _v43_add_vote(votes, "forecast_engine", fscore, "پیش‌بینی مسیر", "FORECAST", True, 0.60)
        reg("forecast", "FORECAST", True)
    else:
        reg("forecast", "FORECAST", False)

    cal = item.get("probability_calibration") if isinstance(item.get("probability_calibration"), dict) else {}
    if cal:
        cval = safe_float(cal.get("calibrated"), 50.0)
        cn = int(safe_float(cal.get("samples"), 0))
        cconf = clamp(cn / 100.0, 0.15, 1.0)
        _v43_add_vote(votes, "realized_calibration", cval, "کالیبراسیون realized", "ROBUSTNESS_LEARNING", True, cconf)
        reg("realized_calibration", "ROBUSTNESS_LEARNING", True, f"samples={cn}")
    else:
        reg("realized_calibration", "ROBUSTNESS_LEARNING", False)

    learning = item.get("v32_learning") or {}
    if isinstance(learning, dict) and learning:
        ladj = safe_float(learning.get("long_adjustment"), 0.0)
        sadj = safe_float(learning.get("short_adjustment"), 0.0)
        lscore = 50.0 + clamp((ladj - sadj) * 2.0, -20.0, 20.0)
        _v43_add_vote(votes, "learning_engine", lscore, "یادگیری تاریخی", "ROBUSTNESS_LEARNING", True, 0.55)
        reg("learning", "ROBUSTNESS_LEARNING", True)
    else:
        reg("learning", "ROBUSTNESS_LEARNING", False)

    # Hard veto aggregation from every downstream safety layer.
    vetoes: list[str] = []
    if v40:
        vetoes.extend([str(v) for v in (v40.get("hard_blocks") or []) if str(v)])
    if v31 and bool(v31.get("safety_wait")):
        vetoes.append("V31 safety_wait")
    if v36 and bool(v36.get("kill")):
        vetoes.append("V36 kill")
    if v36 and bool(v36.get("blocked")):
        vetoes.append("V36 blocked")

    active = [v for v in votes.values() if v.get("v43")]
    groups = {str(v.get("group")) for v in active if v.get("group")}
    participation = {
        "active_components": len(active),
        "active_groups": len(groups),
        "required_components": V43_MIN_COMPONENTS,
        "required_groups": V43_MIN_ACTIVE_GROUPS,
        "sufficient": len(active) >= V43_MIN_COMPONENTS and len(groups) >= V43_MIN_ACTIVE_GROUPS,
        "registry": registry,
        "hard_vetoes": vetoes,
    }
    return votes, participation


def _v43_unified_decide_base(item: dict[str, Any]) -> dict[str, Any]:
    """Re-arbitrate the fully enriched snapshot through one central brain."""
    x = dict(item or {})
    votes, participation = _v43_unified_evidence(x)
    with _CENTRAL_WEIGHT_LOCK:
        weights = dict(_CENTRAL_WEIGHTS)
    # New coordinator weights are intentionally bounded and lower than the
    # primary TF/structure spine to avoid double-counting correlated evidence.
    extra_defaults = {
        "neural_v9": 1.00, "regime_engine": 0.85, "structure_engine": 0.95,
        "liquidity_engine": 0.55, "precision_engine": 0.70, "v31_edge_suite": 0.80,
        "v34_opportunity": 0.70, "v36_horizon": 0.75, "v36_resonance": 0.55,
        "v40_precision": 0.80, "btc_macro_context": 0.55, "forecast_engine": 0.50,
        "realized_calibration": 0.60, "learning_engine": 0.55,
    }
    for k, v in extra_defaults.items():
        weights.setdefault(k, v)

    long_num = short_num = den = 0.0
    details = []
    for name, v in votes.items():
        if name == "data_trust":
            continue
        w = safe_float(weights.get(name), 1.0)
        eff = w * clamp(safe_float(v.get("confidence"), 0.0), 0.0, 1.0)
        lean = clamp(safe_float(v.get("lean"), 0.0), -1.0, 1.0)
        den += eff
        if lean > 0: long_num += eff * lean
        elif lean < 0: short_num += eff * abs(lean)
        details.append({"component": name, "group": v.get("group", "CORE"), "side": v.get("side"),
                        "lean": round(lean, 4), "confidence": round(safe_float(v.get("confidence"), 0), 4),
                        "weight": round(w, 4), "contribution": round(eff * lean, 4), "raw": v.get("raw")})
    long_score = long_num / max(den, 1e-9)
    short_score = short_num / max(den, 1e-9)
    edge = max(long_score, short_score)
    margin = abs(long_score - short_score)
    trust = safe_float((votes.get("data_trust") or {}).get("trust"), 70.0)
    candidate = "LONG" if long_score > short_score else "SHORT" if short_score > long_score else "WAIT"
    reasons = []
    if not participation["sufficient"]:
        reasons.append("اجماع ناکافی: مشارکت ماژول‌ها کم است")
    if trust < _CENTRAL_MIN_TRUST: reasons.append(f"اعتماد داده پایین ({trust:.0f})")
    if edge < _CENTRAL_MIN_EDGE: reasons.append(f"لبه تصمیم ناکافی ({edge:.3f})")
    if margin < _CENTRAL_MIN_MARGIN: reasons.append(f"حاشیه تصمیم کم ({margin:.3f})")
    reasons.extend(participation["hard_vetoes"])

    # Existing overlap gate remains a portfolio-level veto.
    overlap = _edge_overlap_gate(_normalize_symbol(x.get("symbol") or ""), candidate)
    if candidate in {"LONG", "SHORT"} and not overlap.get("ok", True):
        reasons.append(str(overlap.get("reason") or "overlap risk"))

    # Directional level contract is not allowed to be invented at this stage.
    price = _v42_price(x)
    sl = safe_float(x.get("stop_loss_raw"), safe_float(x.get("stop_loss"), 0.0))
    tp1 = safe_float(x.get("tp1_raw"), safe_float(x.get("tp1"), 0.0))
    tp2 = safe_float(x.get("tp2_raw"), safe_float(x.get("tp2"), 0.0))
    if candidate in {"LONG", "SHORT"} and not _v42_levels_ok(price, sl, tp1, tp2, candidate):
        reasons.append("سطوح نهایی با جهت اجماع منطبق نیست")

    decision = candidate if not reasons and candidate in {"LONG", "SHORT"} else "WAIT"
    conf = clamp(50.0 + edge * 38.0 + margin * 28.0 + (trust - 50.0) * 0.12, 5.0, 94.0)
    if decision == "WAIT": conf = min(conf, 55.0)
    scorecard = []
    for d in details:
        scorecard.append({**d, "aligned": decision in {"LONG", "SHORT"} and d["side"] == decision,
                          "opposed": decision in {"LONG", "SHORT"} and d["side"] in {"LONG", "SHORT"} and d["side"] != decision})

    x["decision"] = decision
    x["decision_tag"] = decision
    x["bias"] = "صعودی" if decision == "LONG" else "نزولی" if decision == "SHORT" else "خنثی"
    x["entry_mode"] = "EARLY" if decision in {"LONG", "SHORT"} else "WAIT"
    x["signal_tag"] = f"UNIFIED-CENTRAL — {decision}"
    x["decision_state"] = f"UNIFIED_CENTRAL_{decision}"
    x["decision_confidence"] = round(conf, 2)
    x["directional_bias"] = round((long_score - short_score) * 100.0, 2)
    x["unified_central"] = {
        "version": V43_VERSION, "decision": decision,
        "candidate": candidate, "long_score": round(long_score, 5), "short_score": round(short_score, 5),
        "edge": round(edge, 5), "margin": round(margin, 5), "confidence": round(conf, 2),
        "trust": round(trust, 2), "components": scorecard,
        "weights": {k: round(v, 4) for k, v in weights.items()},
        "participation": participation, "overlap": overlap,
        "reasons": reasons, "authoritative": True, "timestamp": time.time(),
    }
    x["decision_reasons"] = reasons
    x["central_reason_fa"] = " · ".join(reasons[:6]) if reasons else "اجماع کامل شواهد"
    x["decision_architecture"] = {
        **(dict(x.get("decision_architecture") or {}) if isinstance(x.get("decision_architecture"), dict) else {}),
        "type": "ONE_BRAIN_MANY_EVIDENCE_CHANNELS",
        "authoritative_source": V43_VERSION,
        "final_decision": decision,
        "all_available_modules_are_evidence": True,
        "circular_previous_decisions_excluded": True,
        "module_participation": participation,
    }
    x["authority"] = V43_VERSION
    return x

# ---- Public gateways ----
_CENTRAL_PREV_ANALYZE = _analyze_asset_v32_impl
_CENTRAL_PREV_UPDATE = _update_cache_base


def _analyze_asset_central(symbol: str, btc_trend: str) -> Optional[dict[str, Any]]:
    """Sole public analyzer — evidence stack, then V40 precision seal."""
    try:
        base = _CENTRAL_PREV_ANALYZE(symbol, btc_trend)
        if not base:
            return None
        if btc_trend and not base.get("btc_trend"):
            base["btc_trend"] = btc_trend
        sealed = _central_seal(base)
        sealed = _v31_apply(sealed)
        sealed = _v34_apply(sealed)
        snapshot = _v35_get_live_snapshot(symbol)
        sealed = _v35_rebase_price_dependent_outputs(sealed, snapshot)
        try:
            with CACHE_LOCK:
                _rows = list(CACHE.get("data") or [])
        except Exception:
            _rows = []
        sealed = _v36_apply(sealed, _rows)
        sealed = _v40_precision_gate(sealed, _rows)
        # V43 is the actual final arbiter: every enriched module votes here.
        sealed = _v43_unified_decide(sealed)
        sealed = _v42_integrity_seal(sealed)
        try:
            _central_record_prediction(sealed)
        except Exception as rec_exc:
            LOGGER.debug("record after V40: %s", rec_exc)
        return sealed
    except Exception as exc:
        LOGGER.exception("Central analyze failed %s: %s", symbol, exc)
        try:
            if "base" in locals() and base:
                _fb = _v40_precision_gate(_central_seal(base), [])
                _fb = _v43_unified_decide(_fb)
                return _v42_integrity_seal(_fb)
        except Exception:
            _swallow()
        return None


def _update_cache_central(force: bool = False) -> tuple[list[dict[str, Any]], str, dict[str, Any]]:
    """Central-owned scan with progress heartbeat + emergency fallback."""
    coins = list(USER_SETTINGS.get("active_coins") or DEFAULT_COINS)
    total = max(1, len(coins))
    scan_started = time.time()
    with CACHE_LOCK:
        cached_n = len(CACHE.get("data") or [])
        cache_age = time.time() - safe_float(CACHE.get("timestamp"), 0.0)
        cached_data = list(CACHE.get("data") or [])
        cached_summary = CACHE.get("gemini_summary") or ""
        cached_macro = dict(CACHE.get("macro") or {})
    ttl = float(globals().get("MARKET_CACHE_TTL", 40))
    do_force = bool(force) or cached_n <= 0 or cache_age >= ttl

    if not do_force and cached_n > 0:
        _scan_progress_update(
            status="complete", phase="داده از کش", completed=cached_n,
            total=max(total, cached_n), percent=100,
            last_success_at=time.time() - cache_age if cache_age < 1e9 else time.time(),
            message=f"کش تازه · {cached_n} ارز · سن {cache_age:.0f}s", fresh=False,
        )
        return cached_data, cached_summary, cached_macro

    _scan_progress_update(
        status="running", phase="آماده‌سازی داور مرکزی", started_at=scan_started,
        finished_at=0.0, completed=0, total=total, percent=3,
        message=f"داور مرکزی · اسکن {total} ارز…", fresh=False,
    )
    hb_stop = threading.Event()

    def _hb():
        # Fast heartbeat (~0.6s): advances bar from real completed count + mild time blend
        # so the UI never sits at 3% for tens of seconds on a phone.
        while not hb_stop.wait(0.6):
            try:
                snap = _scan_progress_snapshot()
                if str(snap.get("status") or "") != "running":
                    break
                started = safe_float(snap.get("started_at"), scan_started)
                elapsed = max(0.0, time.time() - started)
                completed = int(snap.get("completed") or 0)
                tot = max(1, int(snap.get("total") or total or 1))
                # Completion dominates; time only fills the gap while waiting on first results.
                by_done = 12.0 + (completed / tot) * 78.0
                by_time = 12.0 + min(55.0, elapsed * 4.5)  # ~12s to ~67% if stuck before first finish
                soft = min(94.0, max(by_done, by_time if completed == 0 else by_done))
                cur = safe_float(snap.get("percent"), 0)
                if soft > cur + 0.4:
                    _scan_progress_update(
                        percent=round(soft, 1),
                        message=snap.get("message") or f"تحلیل زنده · {completed}/{tot}",
                    )
            except Exception:
                break

    threading.Thread(target=_hb, name="titan-progress-hb", daemon=True).start()
    try:
        try:
            _central_evaluate_pending()
        except Exception:
            _swallow()
        try:
            if "v32_evaluate_pending" in globals():
                v32_evaluate_pending()
        except Exception:
            _swallow()

        data, summary, macro = _CENTRAL_PREV_UPDATE(True)
        sealed: list[dict[str, Any]] = []
        n_items = max(1, len(data or []))
        for idx, item in enumerate(data or [], 1):
            try:
                if str(item.get("authority", "")) == TITAN_CENTRAL_VERSION:
                    sealed.append(item)
                else:
                    sealed.append(_central_seal(item))
            except Exception:
                if item:
                    sealed.append(item)
            if idx == n_items or idx % 3 == 0:
                _scan_progress_update(
                    completed=idx, total=max(total, n_items),
                    percent=min(98, 85 + int(12 * idx / n_items)),
                    phase="مهر داور مرکزی", message=f"مهر مرکزی {idx}/{n_items}",
                )
        finished = time.time()
        with CACHE_LOCK:
            CACHE["data"] = sealed
            if sealed:
                CACHE["timestamp"] = finished
                if summary is not None:
                    CACHE["gemini_summary"] = summary
                if macro is not None:
                    CACHE["macro"] = macro
        if sealed:
            _scan_progress_update(
                status="complete", phase="اسکن کامل شد", completed=len(sealed),
                total=max(total, len(sealed)), percent=100, finished_at=finished,
                last_success_at=finished, elapsed_sec=round(finished - scan_started, 1),
                message=f"داور مرکزی · {len(sealed)} ارز · {round(finished - scan_started, 1)}s",
                fresh=True,
            )
            try:
                if "store_forecasts" in globals():
                    store_forecasts(sealed)
            except Exception:
                _swallow()
            return sealed, summary, macro

        emergency = _emergency_live_cards(coins)
        if emergency:
            with CACHE_LOCK:
                CACHE["data"] = emergency
                CACHE["timestamp"] = finished
            _scan_progress_update(
                status="complete", phase="قیمت زنده اضطراری", completed=len(emergency),
                total=max(total, len(emergency)), percent=100, finished_at=finished,
                last_success_at=finished,
                message=f"اسکن کامل ناموفق؛ {len(emergency)} قیمت زنده",
                fresh=False,
            )
            return emergency, summary or "", macro or {}
        if cached_n > 0:
            _scan_progress_update(
                status="complete", phase="بازیابی کش", completed=cached_n,
                total=max(total, cached_n), percent=100, finished_at=finished,
                message=f"نمایش {cached_n} ارز از کش", fresh=False,
            )
            return cached_data, cached_summary, cached_macro
        _scan_progress_update(
            status="failed", phase="اسکن بدون نتیجه", percent=100, finished_at=finished,
            message="نتیجه‌ای برنگشت؛ اسکن بعدی خودکار است", fresh=False,
        )
        return [], summary or "", macro or {}
    except Exception as exc:
        LOGGER.exception("Central update_cache: %s", exc)
        finished = time.time()
        try:
            emergency = _emergency_live_cards(coins)
        except Exception:
            emergency = []
        if emergency:
            with CACHE_LOCK:
                CACHE["data"] = emergency
                CACHE["timestamp"] = finished
            _scan_progress_update(
                status="complete", phase="بازیابی اضطراری", percent=100,
                completed=len(emergency), finished_at=finished,
                message=f"خطا در اسکن · {len(emergency)} قیمت زنده", fresh=False,
            )
            return emergency, "", {}
        _scan_progress_update(
            status="failed", phase="خطای اسکن", percent=100, finished_at=finished,
            message=f"خطا: {str(exc)[:200]}", fresh=False,
        )
        with CACHE_LOCK:
            return list(CACHE.get("data") or []), CACHE.get("gemini_summary") or "", CACHE.get("macro") or {}
    finally:
        hb_stop.set()


