# ============================================================
# TITAN V46 — HONEST PERFORMANCE / CALIBRATION / LEARNING PATCH
# ============================================================
# This section is intentionally the LAST authority layer.
#
# Fixes:
# 1) Removes the previous simplistic final decision layer that could overwrite
#    the V45 validated governor with a weaker score-only rule.
# 2) Fixes runtime typos in the old final patch (USERSETTINGS/normalizesymbol).
# 3) Adds an explicit prediction ledger for BOTH published signals and shadow
#    directional candidates. Shadow samples never execute orders.
# 4) Evaluates outcomes chronologically using the exact prediction horizon.
# 5) Uses SL/TP first-touch; same-bar SL+TP is AMBIGUOUS, never a fabricated win.
# 6) Charges round-trip friction and reports gross/net returns and R.
# 7) Adds honest Bayesian posterior metrics. No "50% win rate" is shown for N=0.
# 8) Adds confidence calibration buckets and Wilson lower confidence bound.
# 9) Adds LONG/SHORT + regime + timeframe attribution.
# 10) Adds component/agent attribution and bounded Bayesian weighting.
# 11) Adds walk-forward/OOS audit metadata and leakage guards.
# 12) Adds a production self-test and rich /api/v46/audit endpoint.
#
# Analysis only. No real-order execution is introduced here.
# ============================================================

V46_VERSION = "TITAN-V46-HONEST-LEDGER-CALIBRATED-OOS"

def _ff(v: Any, default: float = 0.0) -> float:
    try:
        x = float(v)
        return x if math.isfinite(x) else default
    except (TypeError, ValueError):
        return default




def _unified_stance(item: dict) -> dict:
    """Single coherent opinion for the whole dashboard.

    Hierarchy:
      1) V51 published LONG/SHORT  -> authoritative trade stance
      2) Strong multi-TF quant lean -> LEAN_LONG / LEAN_SHORT (advisory, not published)
      3) Otherwise WAIT

    Scalp window, breadth, cards, and opportunity center MUST all read this.
    """
    if not isinstance(item, dict):
        return {
            "stance": "WAIT", "stance_family": "WAIT", "published": False,
            "label_fa": "انتظار", "bias": "خنثی", "confidence": 40.0,
            "reason": "no-item",
        }
    tag = str(item.get("decision_tag") or item.get("decision") or "WAIT").upper()
    quant = safe_float(item.get("quant_score"), safe_float(item.get("score"), 50.0))
    tfs = item.get("tf_scores") or item.get("tfs") or {}
    if not isinstance(tfs, dict):
        tfs = {}
    s15 = safe_float(tfs.get("15m"), quant)
    s1h = safe_float(tfs.get("1h"), quant)
    s4h = safe_float(tfs.get("4h"), quant)
    sq = safe_float(item.get("signal_quality"), abs(quant - 50.0) * 1.2 + 40.0)
    # Alignment of short TFs with quant
    long_align = (s15 >= 52) + (s1h >= 50) + (s4h >= 52) + (quant >= 55)
    short_align = (s15 <= 48) + (s1h <= 50) + (s4h <= 48) + (quant <= 45)

    if tag == "LONG":
        return {
            "stance": "LONG", "stance_family": "LONG", "published": True,
            "label_fa": "لانگ فعال", "bias": "صعودی",
            "confidence": float(clamp(max(sq, quant), 55, 95)),
            "reason": "v51-published",
        }
    if tag == "SHORT":
        return {
            "stance": "SHORT", "stance_family": "SHORT", "published": True,
            "label_fa": "شورت فعال", "bias": "نزولی",
            "confidence": float(clamp(max(sq, 100 - quant), 55, 95)),
            "reason": "v51-published",
        }

    # Lean thresholds: balanced — more real leans, still require TF agreement (no fake flips)
    strong_long = quant >= 62 and long_align >= 2 and s15 >= 53
    strong_short = quant <= 38 and short_align >= 2 and s15 <= 47
    mild_long = quant >= 55 and long_align >= 2 and (s15 >= 50 or s1h >= 50)
    mild_short = quant <= 45 and short_align >= 2 and (s15 <= 50 or s1h <= 50)

    if strong_long:
        return {
            "stance": "LEAN_LONG", "stance_family": "LONG", "published": False,
            "label_fa": "تمایل صعودی", "bias": "صعودی",
            "confidence": float(clamp(50 + (quant - 50) * 0.9 + long_align * 3, 55, 88)),
            "reason": "quant-strong-long",
        }
    if strong_short:
        return {
            "stance": "LEAN_SHORT", "stance_family": "SHORT", "published": False,
            "label_fa": "تمایل نزولی", "bias": "نزولی",
            "confidence": float(clamp(50 + (50 - quant) * 0.9 + short_align * 3, 55, 88)),
            "reason": "quant-strong-short",
        }
    if mild_long:
        return {
            "stance": "LEAN_LONG", "stance_family": "LONG", "published": False,
            "label_fa": "تمایل صعودی ملایم", "bias": "صعودی",
            "confidence": float(clamp(48 + (quant - 50) * 0.7, 50, 75)),
            "reason": "quant-mild-long",
        }
    if mild_short:
        return {
            "stance": "LEAN_SHORT", "stance_family": "SHORT", "published": False,
            "label_fa": "تمایل نزولی ملایم", "bias": "نزولی",
            "confidence": float(clamp(48 + (50 - quant) * 0.7, 50, 75)),
            "reason": "quant-mild-short",
        }
    return {
        "stance": "WAIT", "stance_family": "WAIT", "published": False,
        "label_fa": "انتظار / خنثی", "bias": "خنثی",
        "confidence": float(clamp(40 + (20 - abs(quant - 50)) * 0.5, 35, 55)),
        "reason": "neutral",
    }


def _dashboard_finalize_item(item):
    """Last-mile card hygiene: identity + numeric TF scores + non-collapsed display score."""
    if not isinstance(item, dict):
        return item
    x = dict(item)
    sym = _normalize_symbol(str(x.get("symbol") or ""))
    if sym:
        base = sym.split("/")[0].upper()
        meta = COIN_META.get(base, (base, "●"))
        x["symbol"] = sym
        x["base_symbol"] = str(x.get("base_symbol") or base)
        x["coin_name"] = str(x.get("coin_name") or meta[0] or base)
        x["coin_icon"] = str(x.get("coin_icon") or meta[1] or "●")
        x["tv_symbol"] = str(x.get("tv_symbol") or _binance_symbol(sym))
    numeric = {}
    for src_key in ("tf_scores", "tfscores", "tfs"):
        src = x.get(src_key)
        if not isinstance(src, dict):
            continue
        for k, v in src.items():
            try:
                fv = float(v)
                if math.isfinite(fv) and 0.0 <= fv <= 100.0:
                    # Prefer non-neutral values when merging sources
                    prev = numeric.get(str(k))
                    if prev is None or (abs(prev - 50.0) < 0.5 and abs(fv - 50.0) >= 0.5):
                        numeric[str(k)] = float(fv)
                    elif prev is None:
                        numeric[str(k)] = float(fv)
            except (TypeError, ValueError):
                continue
    for tf, flat in (("15m", "tfs15m"), ("1h", "tfs1h"), ("4h", "tfs4h"), ("1d", "tfs1d")):
        if tf not in numeric:
            try:
                fv = float(x.get(flat))
                if math.isfinite(fv):
                    numeric[tf] = float(clamp(fv, 0, 100))
            except (TypeError, ValueError):
                _swallow()
    quant = safe_float(x.get("quant_score"), safe_float(x.get("score"), 50.0))
    if numeric:
        try:
            wavg = float(sum(numeric.get(t, quant) * TF_CFG[t]["weight"] for t in TF_CFG))
        except Exception:
            wavg = float(sum(numeric.values()) / max(1, len(numeric)))
        # If stored quant is neutral but TF map is not, trust the TF map
        if abs(quant - 50.0) < 0.5 and abs(wavg - 50.0) >= 0.5:
            quant = wavg
        elif abs(quant - 50.0) < 0.5:
            quant = wavg
    else:
        numeric = {"15m": quant, "1h": quant, "4h": quant, "1d": quant}
    for tf in ("15m", "1h", "4h", "1d"):
        numeric.setdefault(tf, quant)
        x["tfs" + tf] = round(float(numeric[tf]), 1)
    x["tfs"] = {k: round(float(numeric[k]), 1) for k in ("15m", "1h", "4h", "1d")}
    x["tf_scores"] = dict(x["tfs"])
    x["tfscores"] = dict(x["tfs"])
    quant = float(clamp(quant, 0, 100))
    x["quant_score"] = int(round(quant))
    x["score"] = int(round(quant))
    x["score_bar"] = int(round(quant))
    x["score_color"] = "#4ade80" if quant >= 60 else "#f43f5e" if quant <= 40 else "#fbbf24"
    sq = safe_float(x.get("signal_quality"), 0.0)
    if sq <= 1.0 or (sq == 40.0 and abs(quant - 50.0) >= 1.0):
        x["signal_quality"] = round(clamp(abs(quant - 50.0) * 1.5 + 35.0, 5, 95), 1)
    if not x.get("decision_tag"):
        x["decision_tag"] = str(x.get("decision") or "WAIT").upper()
    if not x.get("bias") or x.get("bias") == "خنثی":
        tag = str(x.get("decision_tag") or "WAIT").upper()
        if tag == "LONG":
            x["bias"] = "صعودی"
        elif tag == "SHORT":
            x["bias"] = "نزولی"
        elif quant >= 58:
            x["bias"] = "صعودی"
        elif quant <= 42:
            x["bias"] = "نزولی"
        else:
            x["bias"] = "خنثی"
    # Ensure fusion/edge/titan_analysis are maps (prevents Jinja str.get crashes)
    for key in ("fusion", "edge", "titan_analysis", "data_quality", "patterns", "candle_forecast", "signal_grade", "macd", "stoch_rsi", "session", "buy_sell"):
        if key in x and not isinstance(x.get(key), dict):
            x[key] = {}
    # Unified central stance — one opinion for cards / breadth / scalp / opportunity
    st = _unified_stance(x)
    x["stance"] = st["stance"]
    x["stance_family"] = st["stance_family"]
    x["stance_published"] = bool(st["published"])
    x["stance_label"] = st["label_fa"]
    x["stance_confidence"] = round(float(st["confidence"]), 1)
    x["stance_reason"] = st["reason"]
    x["bias"] = st["bias"]
    # Display decision: published tags stay; leans show as LEAN_*; pure wait stays WAIT
    if st["published"]:
        x["decision_display"] = st["stance"]
        x["decision_tag"] = st["stance"]
    else:
        x["decision_display"] = st["stance"]  # LEAN_LONG / LEAN_SHORT / WAIT
        # Keep authority decision_tag as WAIT when not published (ledger safety)
        if str(x.get("decision_tag") or "").upper() not in {"LONG", "SHORT"}:
            x["decision_tag"] = "WAIT"
    # Card chrome
    if st["stance_family"] == "LONG":
        x["score_color"] = "#4ade80" if quant >= 60 else "#86efac"
    elif st["stance_family"] == "SHORT":
        x["score_color"] = "#f43f5e" if quant <= 40 else "#fb7185"
    else:
        x["score_color"] = "#fbbf24"
    # Grade reflects stance so middle/bottom boards match top
    if st["published"]:
        x["grade"] = x.get("grade") if x.get("grade") in {"A+", "A", "B"} else "A"
    elif st["stance"] in {"LEAN_LONG", "LEAN_SHORT"}:
        # Strong lean -> B (watch/active), mild stays C
        if st["reason"] in {"quant-strong-long", "quant-strong-short"}:
            x["grade"] = "B"
        else:
            x["grade"] = x.get("grade") if x.get("grade") not in {None, "", "—"} else "C"
        # opportunity state for boards
        x["opportunity_state"] = "EARLY_" + st["stance_family"]
        x["opportunity_score"] = max(safe_float(x.get("opportunity_score"), 0), float(st["confidence"]))
    else:
        if str(x.get("grade") or "") in {"A+", "A"}:
            x["grade"] = "C"  # no fake A on pure WAIT
    # signal_grade map stay consistent
    sg = x.get("signal_grade") if isinstance(x.get("signal_grade"), dict) else {}
    sg = dict(sg)
    sg["grade"] = x.get("grade") or sg.get("grade") or "C"
    sg["label_fa"] = st["label_fa"]
    sg["action"] = "PUBLISH" if st["published"] else ("LEAN" if st["stance_family"] in {"LONG", "SHORT"} else "WAIT")
    sg["trust_index"] = round(float(st["confidence"]), 1)
    x["signal_grade"] = sg
    x["signal_tag"] = f"STANCE {st['stance']} · {st['label_fa']}"
    try:
        x = _v61_attach_flow(x) or x
    except Exception:
        _swallow()
    return x


def _normalise_dashboard(rows):
    """Ensure every dashboard card has display identity + numeric TF scores + safe AI block."""
    out=[]
    for raw in rows or []:
        if not isinstance(raw, dict):
            continue
        x = _dashboard_finalize_item(dict(raw)) or dict(raw)
        # AI opinions safety for template
        ai = x.get("ai_opinions")
        if not isinstance(ai, dict):
            ai = {}
        else:
            ai = dict(ai)
        status = ai.get("ai_status")
        if not isinstance(status, dict):
            status = {
                "gemini": str(status) if status else "در انتظار تحلیل",
                "openai": "در انتظار تحلیل",
                "grok": "در انتظار تحلیل",
                "claude": "در انتظار تحلیل",
                "deepseek": "در انتظار تحلیل",
            }
        ai["ai_status"] = status
        if not ai.get("internal"):
            ta = x.get("titan_analysis")
            ai["internal"] = str((ta or {}).get("summary") or "") if isinstance(ta, dict) else ""
        x["ai_opinions"] = ai
        if not x.get("price") and x.get("price_raw"):
            x["price"] = smart_format(x.get("price_raw"))
        out.append(x)
    return out


