_V48_PREV_ANALYZE = _analyze_asset_v47

def _analyze_asset_v48(symbol: str, btc_trend: str) -> Optional[dict[str, Any]]:
    try:
        base=_V48_PREV_ANALYZE(symbol,btc_trend)
        if not base:return base
        out=_v48_apply_opportunity(base)
        try:_v48_record(out)
        except Exception:_swallow()
        return out
    except Exception as exc:
        LOGGER.exception("V48 analyze wrapper failed for %s: %s",symbol,exc)
        return None

_V48_PREV_UPDATE = _update_cache_v47

def _update_cache_v48(force: bool=False):
    try:_v48_evaluate_pending(limit=120)
    except Exception:_swallow()
    return _V48_PREV_UPDATE(force)


