def _v55_self_test() -> int:
    fails = []
    def chk(n, c):
        print(("  ✓ " if c else "  ✗ ") + n)
        if not c:
            fails.append(n)
    sample = {
        "symbol": "BTC/USDT", "decision": "LONG", "decision_state": "V53_READY_FOR_PUBLICATION",
        "trust": 70, "signal_quality": 60, "effective_rr_tp1": 1.5, "score": 68, "grade": "A",
        "price_raw": 100.0, "stop_loss_raw": 97.0, "tp1_raw": 105.0, "tp2_raw": 110.0,
        "data_contract": {"live_age_sec": 2.0},
    }
    ok, reason = _v55_publish_gate(sample)
    chk("gate_ok", ok and reason == "OK")
    bad = dict(sample); bad["stop_loss_raw"] = 102.0
    chk("invalid_levels", not _v55_publish_gate(bad)[0])
    stale = dict(sample); stale["data_contract"] = {"live_age_sec": 99}
    chk("stale", _v55_publish_gate(stale)[1] == "STALE_PRICE")
    chk("rank_positive", _v55_score_rank(sample) > 20)
    interval = v55_adapt_scan_interval(3000)
    chk("adapt_floor", V55_SCAN_ADAPT_FLOOR <= interval <= V55_SCAN_ADAPT_CEIL)
    print("V55 SELF-TEST:", "PASS" if not fails else "FAIL " + ",".join(fails))
    return 0 if not fails else 1




