def _v62_patch_self_test() -> int:
    failures = []
    def check(name, condition):
        if not condition:
            failures.append(name)
            print("  FAIL", name)
        else:
            print("  PASS", name)
    check("missing string -> None", _v62_optional_float("N/A") is None)
    check("invalid numeric -> None", _v62_optional_float(float("nan")) is None)
    check("actual zero preserved", _v62_optional_float(0) == 0.0)
    empty = _v62_flow_score(None, None, None, None, None)
    check("no data is unavailable, not 50", empty.get("score") is None and empty.get("bias") == "unavailable")
    partial = _v62_flow_score(60.0, None, None, None, None)
    check("partial data counts only observed components", partial.get("live_components") == 1 and partial.get("score") == 70.0)
    check("flow weights remain normalized", abs(sum(_V62_FLOW_WEIGHTS.values()) - 1.0) < 0.02)
    if failures:
        print("V62.1 SELF-TEST FAILED:", ", ".join(failures))
        return 1
    print("V62.1 SELF-TEST PASSED")
    return 0



